// DE VOORWAARDEN VAN EEN REGEL — overal dezelfde rij.
//
// Een voorwaarde is DRIE SLOTS op één knoop: grootheid (odrl:leftOperand),
// operator (odrl:operator) en waarde (odrl:rightOperand). De weergave toont die
// drie als chips, en degradeert in WOORDEN, niet in VORM: een operator zonder
// label wordt "ex:opX" in de operator-chip, een slot dat écht ontbreekt krijgt
// een waarschuwings-chip. Zo verspringt de structuur van een kaart niet zodra
// de data wat magerder is.
//
// Gedragsbron: constraintsSection, constraintItem en conformsChips in de
// bevroren `viewer-bevroren/assets/doc.js`; de zin- en slotstructuur zelf komt uit
// `constraintSentence` in de modellaag (parse.js) en wordt hier NIET herbouwd.
//
// DIT BESTAND IS DE RIJ, NIET DE INHOUD. De chips, de logische groep en de
// gedeelde ingang `VoorwaardeInhoud` staan sinds de dt3-opruiming in
// `voorwaarde-inhoud.tsx` — die laag kent het invulling-paneel niet en kan dus
// door `invulling.tsx` worden gelezen zonder de importlus die hier stond (zie de
// kop van dat bestand en `cyclus.test.ts`). Wat hier blijft is de rij mét haar
// twee uitgangen, en die kant kán niet verhuizen: `InvullingKnop` leunt op de
// paneelmachinerie.
//
// DRIE BEWUSTE AFWIJKINGEN (verbeteringen, besluit 4 sep) — elk hieronder bij
// zijn code toegelicht:
//   2. geneste and/or als GROEPS-WIDGET: de groep is een echte `role="group"`
//      met een naam, haar kop draagt het aantal leden, en elk niveau stempelt
//      zijn nestdiepte zodat de inspringing meeschaalt.
//   3. rdf:List-rechteroperanden als LIJST MET TRUNCATIE: de "… (n waarden)"-
//      chip met de volledige lijst in een hover is een KNOP "toon alle n"
//      geworden.
//   5. de DOELBINDING (purpose-refinement) prominent: zij stond vooraan maar
//      zag er uit als elke andere rij; nu draagt zij haar eigen merk en accent.
//
// DE TWEE UITGANGEN van een rij — ⌕ naar de graaf, ⚙ naar het invulling-paneel
// (voorwaardeStrook/conditionGear) — staan er sinds de gaten-ronde op; zie
// VoorwaardeRij en VoorwaardeInvullingKnop (bevindingen C-1 en I-2).
//
// DE UITKLAP VAN EEN RIJ IS GENERIEK (eigenaarsbesluit 15 sep 2026). Tot deze
// ronde hing zij aan `ArtefactVouw` in `formulier-artefact.tsx`, en die sloeg aan
// op de ODRL-AP-NL-operator `apnl:conformsToPolicy` plus de dpv-marker
// `dpv:TechnicalMeasure` — profielkennis in de viewerkern. Eigenaar, op het
// voorstel om datzelfde idioom uit te breiden: "Dat klinkt als ODRL-AP-NL
// specifiek iets in de viewer. Dat is niet de bedoeling."
//
// Wat ervoor in de plaats komt bestond al, één laag verderop: `RijVouw`
// (formulier.tsx) klapt ELKE waarde-chip open waarvan de knoop door een geladen
// SHACL-vormshape wordt gedekt — dezelfde vraag (`dektKnoop`) die de
// "overige eigenschappen"-rijen en de doelwitrij al stellen. Een artefact is
// daar geen uitzondering meer in: de meegeleverde artefactshape telt sindsdien
// gewoon mee in de dekking (zie `dektKnoop` in formulier-model.ts).
//
// DE VASTE ZIN IS ER OOK UIT. `ConformsChips` zette op zo'n rij drie chips neer
// die niet uit de data kwamen maar uit de taalbestanden ("verwerkingsverzoek
// voldoet aan beleid <artefact>"), ongeacht wat de leftOperand van de bron zei.
// Dat is dezelfde profielaanname, en zij was al als fout gemeld in de data zelf
// (data/vlierdam/hardening-beleid.ttl: "Op het scherm staat dus het woord
// verzoek waar de bron de toestand zegt … Voor een hardeningsprofiel zou de
// linkerchip uit het label van de leftOperand moeten komen"). De rij leest nu
// haar eigen slots, zoals elke andere voorwaarde. Op het vlierdam- en
// breda-corpus verandert dat niets: daar STAAT `apnl:verwerkingsverzoek` als
// leftOperand en draagt `apnl:conformsToPolicy` het label "voldoet aan beleid".
//
// WAT HIER (NOG) NIET IN ZIT, met opzet:
//   - de UITLEG-tooltip bij een chip (`descriptionFor`): die leest de graaf, en
//     die zit achter de worker-grens. `slots.*.desc` komt wél mee uit het model
//     en staat als `data-desc` op de chip, zodat de taak die de tooltip
//     herbouwt hem hier aanhaakt zonder deze component te wijzigen.
import { For, Show, createMemo, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { coverageNext, PROFILE_PATTERNS } from '../../model/parse.js';
import { actieveDimensies } from '../lijst/pivot.jsx';
import { tekst } from '../../stores/weergave.js';
import { Chevron } from '../gedeeld/chip.jsx';
import { TermKop } from '../gedeeld/kop.jsx';
import { KnoopKeten, RijVouw } from './formulier.jsx';
import { dektKnoop } from './formulier-model.js';
import { bewerklaagActief, Haak } from '../gedeeld/bewerkhaak.jsx';
import { Veld } from '../bewerk/haken.jsx';
import { InvullingKnop } from './invulling.jsx';
import type { Regel } from './kaart.jsx';
import {
  ChipRuimte, ConstraintChips, ConstraintKnoop, GROEP_INKLAP_BLADEN, Noot,
  logischeKop, telBladen, titelVan, vouwWaarde,
} from './voorwaarde-inhoud.jsx';
import type { Voorwaarde } from './voorwaarde-inhoud.jsx';
import './voorwaarden.css';
import { kopBediening } from '../gedeeld/kopselectie.js';

/** Een grote en/of-boom: ingeklapt starten met label en samenvatting, en de
 *  groep pas bouwen als de lezer haar opent (zoals de bevroren viewer).
 *
 *  DE CHEVRON IS DE GEWONE `Chevron` GEWORDEN (15 sep 2026). Hier stond de
 *  laatste `vl-chevron` van de app: een tekstglyph "▸" van 10px, vooraan de
 *  regel. Eigenaar over diezelfde glyph op de conformsToPolicy-rij: "het is nog
 *  de tiiiiny variant die bijna niet te zien is." Dat oordeel gaat niet over die
 *  ene rij maar over de glyph, dus gaat hij overal weg — en hij verhuist naar
 *  het EINDE van de kopregel, waar `gedeeld.css` hem hoort ("ALTIJD als laatste
 *  element van een kopregel"). */
function GroteGroep(props: { c: Voorwaarde }): JSX.Element {
  const [open, setOpen] = createSignal(false);
  const samenvatting = () => tekst('constraint.foldSummary', {
    label: props.c.label || tekst('constraint.compound'),
    head: logischeKop(props.c.logical as string),
    n: telBladen(props.c),
  });
  return (
    <details class="c-fold" onToggle={(e) => setOpen(e.currentTarget.open)}>
      <summary class="vl-summary muted" {...kopBediening()}>
        <span>{samenvatting()}</span>
        <Chevron klein />
      </summary>
      <div class="c-fold-body">
        <Show when={open()}>
          <ConstraintKnoop c={{ ...props.c, label: null }} />
        </Show>
      </div>
    </details>
  );
}

/** Eén voorwaarde-rij. Drie vormen: slot-voorwaarde, logische groep, en de
 *  terugval (geen slots, geen leden) — die houdt óók de chip-structuur. De
 *  vierde vorm van de bevroren viewer, de technische borging met haar eigen
 *  chips en haar eigen uitklap, is vervallen: zie de kop van dit bestand. */
export function VoorwaardeRij(props: {
  c: Voorwaarde;
  scope?: string | null;
  /** De REGEL waaronder deze voorwaarde hangt. De bewerklaag heeft hem nodig om
   *  het anker te vinden: een voorwaarde mag als `odrl:refinement` onder de
   *  (blanke) actie-knoop van die regel zitten, en die is van buitenaf niet aan
   *  te wijzen. De leesweergave doet er niets mee. */
  regel?: Regel | null;
}): JSX.Element {
  const c = () => props.c;
  const borging = () => !!(c().technicalMeasure && c().conformsOp && c().conformsTo);
  const groot = () => !!(c().logical && (c().children || []).length
    && telBladen(c()) > GROEP_INKLAP_BLADEN);
  const genest = () => !!(c().logical && (c().children || []).length);
  // DE WAARDE ACHTER DEZE RIJ. Dekt een geladen formulier-shape haar, dan wordt
  // de rij een UITKLAP met de chevron op die chip; dekt er geen, dan blijft zij
  // letterlijk de chip-rij die zij was. Alleen op een BLAD: een logische groep
  // heeft geen eigen rechterwaarde, en haar leden dragen hun eigen rijen.
  const vouwIri = () => (genest() ? null : vouwWaarde(c(), dektKnoop));
  /** Het adres van deze rij: hetzelfde dat `data-ref` draagt. Een blanke
   *  voorwaarde heeft er geen; dan valt de plek terug op haar zin, want twee
   *  naamloze rijen onder één regel zijn nog steeds twee plekken. */
  const plek = () => c().rowRef || c().iri || c().sentence || '';
  /* DE TWEE UITGANGEN VAN EEN VOORWAARDE-RIJ (voorwaardeStrook in de bevroren
     viewer, `voor: [verkenBtn(c.term), conditionGear(c, scope)]`): ⌕ naar de
     graaf, ⚙ naar de invulling. Ze staan op ELKE vorm van de rij — chip-rij,
     logische groep, terugval én technische borging — en in diezelfde volgorde.
     Vóór deze fix stond er alleen op de borgingsrij een ⚙ (bevinding I-2: 10
     voorwaarderijen op vlierdam zonder paneelingang, 24 ⚙ oud tegen 14 nieuw)
     en nergens een ⌕ (bevinding C-1).
     Bij een VOUW verhuizen ze mee naar binnen: ze horen op de KOPREGEL van de
     uitklap, zodat er per rij één rechtergroep is en het ⚙ ook bereikbaar
     blijft als de vouw dicht staat. */
  const uitgangen = () => (
    <>
      {/* Elk van de twee uitgangen krijgt zijn kopieerbare spatie: zij staan
          in de flexrij van `.constraint`, waar alleen een `gap: 10px` ze van
          de zin ervoor scheidde ("Alleen eigen gemeente⌕"). */}
      <ChipRuimte />
      <ChipRuimte />
      <VoorwaardeInvullingKnop c={c()} scope={props.scope ?? null} />
    </>
  );
  /* DE ACTIESTROOK van de voorwaarderij, ná ⌕ en ⚙ — zodat er per rij één
     rechtergroep is in plaats van twee losse groepjes.
     Ook een GETTER, en om dezelfde reden als `uitgangen()`: de twee takken
     hieronder (met en zonder vouw) mogen niet dezelfde JSX-node delen.
     Bij een VOUW staat hij op dezelfde plek — de kopregel ÍS de rij, dus de
     volgorde chips · ⌕ · ⚙ · strook verandert niet mee. Dat is het verschil met
     de artefactvouw die hij verving: die had een eigen kopregel met de chevron
     helemaal rechts, en dan moest de strook er nog vóór. */
  const strook = () => (
    <Haak
      naam="voorwaardeStrook"
      ctx={{ c: c(), regel: props.regel ?? null, scope: props.scope ?? null }}
    />
  );
  /* EEN BLANKE VOORWAARDE KAN HIER EEN NAAM KRIJGEN (opruimpunt 37).
     De lege-hergebruiklijst zegt: *"Een blanke voorwaarde is niet aan te
     wijzen; geef haar eerst een naam (IRI)."* Die zin is overgenomen van de
     regelkant, waar een blanke rij sinds `lane/knoophergebruik` een
     `vorm: 'knoopIri'`-affordance draagt — en hier bestond die niet. De lezer
     werd dus naar een knop gewezen die er niet was. Dit is dezelfde chip,
     dezelfde mutatie (`benoemKnoop`) en dezelfde stand als op de kaartkop
     (`kaart.tsx`), de blanke partijgroep (`body-rijen.tsx`) en de blanke
     regelrij (`regels.tsx`); vierde plek, geen vierde mechanisme.

     NIET OP DE BORGINGSRIJ. Die is blank BY DESIGN — `parse.js` geeft haar om
     precies die reden een samengestelde `rowRef` — en haar naam is niet wat
     haar aanwijsbaar maakt: zij hangt aan haar artefact, niet aan de
     ↻-hergebruiklijst waar deze belofte over gaat.

     In de KIJKSTAND rendert `Veld` letterlijk zijn kinderen — hier geen — dus
     daar verandert er geen pixel, net als op de drie bestaande plekken. */
  const naamAffordance = () => (
    <Show when={!c().iri && !borging() && (c() as { term?: unknown }).term}>
      <Veld spec={{
        term: (c() as { term?: unknown }).term,
        soort: 'iri',
        preds: [],
        vorm: 'knoopIri',
        iri: null,
      }}
      />
    </Show>
  );
  return (
    <li
      class={'constraint'
        + (c().doelbinding ? ' doelbinding' : '')
        + (borging() ? ' technisch' : '')}
      title={titelVan(c())}
      // data-ref: het adres waarop het invulling-paneel en de dekkingsuitklap
      // deze rij aanwijzen. Een blanke voorwaarde heeft geen knoop en dus geen
      // adres (zie het data-ref-contract van taak 4).
      data-ref={c().rowRef || c().iri || undefined}
    >
      {/* HIER STOND HET MERK "doelbinding" (verbetering 5, besluit 4 sep). Weg
          per EIGENAARSBESLUIT 9 sep 2026, letterlijk: "De AP-NL doelbinding
          hebben we vervangen door het ondersteunen van een dimensie. De viewer
          moet nérgens AP-NL specifiek gemaakt zijn. Badge weghalen íncl code
          dus." Een purpose-refinement is sindsdien een gewone dimensie: de
          groepering (qb:DimensionProperty) en het dimensievakje doen het werk,
          en die zijn profielloos. Een chip die één profielafspraak benoemt zou
          dat mechanisme juist weer aan AP-NL vastknopen.
          De KLASSE `doelbinding` op de rij blijft staan: die is geen weergave
          maar het adres waarop de bewerklaag de purpose-refinement aanwijst
          (`doelbindingTerm` in ui/bewerk/integratie/slots.ts). */}
      {/* DE AANHECHTPLEK VAN DEZE RIJ (zie `KnoopKeten` in formulier.tsx). De
          open-sleutel van een vouw is de keten van voorouders vanaf de PLEK, en
          deze rij is één plek: haar eigen adres. Twee rijen naar dezelfde knoop
          — dezelfde bundel op het anker van twee regels — zijn daarmee twee
          administraties, en klapt de lezer er één open, dan blijft de ander
          dicht. Zonder deze schakel zouden ze één sleutel delen en zou een
          herlading er twee openklappen waar er één geopend was (les 14 sep). */}
      <KnoopKeten.Provider value={[`vw:${props.scope || ''}|${plek()}`]}>
        <RijVouw
          iri={vouwIri()}
          kop={(chevron) => (
            <>
              <Show when={genest()} fallback={(
                <>
                  <ConstraintChips c={c()} vouwIri={vouwIri()} chevron={chevron} />
                  <Noot c={c()} />
                </>
              )}
              >
                <Show when={groot()} fallback={<ConstraintKnoop c={c()} />}>
                  <GroteGroep c={c()} />
                </Show>
              </Show>
              {naamAffordance()}
              {uitgangen()}
              {strook()}
            </>
          )}
        />
      </KnoopKeten.Provider>
      {/* GEEN STROOK BUITEN DE KOPREGEL. Zij stond ooit als broer van de vouw op
          de `li` en kwam daarmee NA de chevron van de artefactvouw — die stond
          dan middenin de rij. Sinds het review-oordeel bij de golf B-fold hoort
          zij in de kopregel, en met de rijvouw is die kopregel de rij zelf: één
          plek voor beide standen. `formulier-vouw.test.tsx` pint dat vast,
          inclusief dat het er per rij ÉÉN is. */}
    </li>
  );
}

/** HET RADERWIEL BIJ ÉÉN VOORWAARDE — `conditionGear` (doc.js r.4323), regel
 *  voor regel:
 *
 *    1. een BLANKE voorwaarde is niet dekbaar en zwijgt altijd; enige
 *       uitzondering is de rij van de technische borging, die blank mág zijn en
 *       juist de spil van de keten vormt (zij is altijd ingevuld, door haar
 *       artefact);
 *    2. de borgingsrij hangt aan haar `rowRef` — die rij is een blanke knoop en
 *       heeft geen eigen IRI;
 *    3. anders alleen wanneer er een VOLGENDE STAP is: een voorwaarde die
 *       niemand uitwerkt heeft niets om open te klappen, en "niet ingevuld" zou
 *       een oordeel zijn op een plek waar de lezer niets kan nakijken. */
export function VoorwaardeInvullingKnop(props: {
  c: Voorwaarde; scope?: string | null;
}): JSX.Element {
  const c = () => props.c;
  const borging = () => !!c().technicalMeasure;
  const doel = () => {
    if (!c().iri && !borging()) return null;
    if (borging()) return c().rowRef || null;
    return (coverageNext(c()) as unknown[]).length ? c().iri || null : null;
  };
  return (
    <Show when={doel()}>{(d) => (
      <InvullingKnop doel={d()} scope={props.scope ?? null} />
    )}</Show>
  );
}

/** De voorwaarden van één regel, in leesvolgorde: eerst de doelbinding (het
 *  purpose-refinement), dan de eigen voorwaarden (odrl:constraint) en de
 *  overige action-refinements.
 *
 *  De DOELBINDING is óók een voorwaarde, maar zij staat in het model in een
 *  eigen veld (`purpose`, met `purposeConstraint` als haar knoop); de weergave
 *  stelt haar rij daarom zelf samen uit die twee. */
export function voorwaardeLijst(regel: Regel, getoondeDims?: string[]): Voorwaarde[] {
  const lijst: Voorwaarde[] = [
    ...((regel.constraints || []) as Voorwaarde[]),
    ...((regel.refinements || []) as Voorwaarde[]),
  ];
  const p = regel.purpose as (Regel['purpose'] & {
    operatorWord?: string; operatorDesc?: string;
  }) | null | undefined;
  if (!p) return lijst;
  // DE DOELBINDING ZWIJGT ZODRA EEN OMHULLENDE GROEPSRIJ HAAR AL ZEGT — de
  // `shownDims`/`purposeShown`-regel van `permissionRow`. Zij zat tot het
  // vervallen van de Doel-rij (eigenaarsbesluit 8 sep 2026) op dat veld; nu
  // hoort zij hier, want dit is de enige plek waar de doelbinding nog staat.
  //
  // MAAR NIET IN DE BEWERKSTAND. Daar is deze rij de énige route naar de
  // doelbinding (het Doel-veld bestaat niet meer), en een rij verbergen omdat de
  // kop erboven hem herhaalt zou hem ONBEWERKBAAR maken binnen een
  // dimensie-weergave. Zelfde afweging, en dezelfde uitkomst, als bij `actieRij`
  // in `regels.tsx`: de kijkstand houdt de bevroren vorm, de bewerkstand toont
  // wat je moet kunnen aanraken.
  if ((getoondeDims || []).includes(PROFILE_PATTERNS.purposeLeftOperand)
    && !bewerklaagActief()) return lijst;
  const pc = ((regel as { purposeConstraint?: Voorwaarde }).purposeConstraint
    || {}) as Voorwaarde;
  lijst.unshift({
    // DE HELE KNOOP EERST, dan de weergavevelden eroverheen. De doelbinding is
    // een SAMENGESTELDE rij (het model heeft haar in twee velden: `purpose` en
    // `purposeConstraint`), maar zij blijft één en dezelfde voorwaarde-knoop:
    // haar dekking (`coverage.next`) hangt eraan, en zonder die velden zou de
    // rij haar raderwiel verliezen. Gemeten op vlierdam: 2 ⚙ minder dan de
    // bevroren viewer, precies op de twee doelbindingsrijen (bevinding I-2).
    ...pc,
    slots: {
      // Links odrl:purpose uit de kern (de ODRL-betekenis van "doel", niet de
      // invulling die een profiel eraan geeft), rechts het doel uit de data.
      left: { text: tekst('left.purpose'), desc: '' },
      operator: { text: p.operatorWord || tekst('op.eq'), desc: p.operatorDesc || '' },
      right: { texts: [p.label || ''], descs: [p.desc || ''] },
    },
    iri: pc.iri || null,
    label: pc.label || null,
    comment: pc.comment || null,
    organisational: !!pc.organisational,
    doelbinding: true,
    unknownProps: [],
  });
  return lijst;
}

/** De Voorwaarden-sectie in de body van een regelrij: kopje + de rijen. Geen
 *  voorwaarden, geen sectie — er valt dan niets te benoemen. */
export function Voorwaarden(props: {
  regel: Regel; scope?: string | null;
  /** De dimensies die de groepsrijen erboven al tonen; zie `voorwaardeLijst`. */
  getoondeDims?: string[];
}): JSX.Element {
  const lijst = createMemo(() => voorwaardeLijst(props.regel, props.getoondeDims));
  return (
    <Show when={lijst().length || bewerklaagActief()}>
      <TermKop tag="h4" sleutel="head.constraints" />
      <ul class="clean constraints">
        <For each={lijst()}>{(c) => (
          <VoorwaardeRij c={c} scope={props.scope} regel={props.regel} />
        )}</For>
        {/* De ghost sluit de lijst af, op de plek waar de nieuwe rij komt.
            `dims`: de groeperingskeuze van de lezer, die de bewerklaag nodig
            heeft voor de snelkoppeling naar de groeperingsvoorwaarde — en die
            zij niet zelf mag ophalen (zie `RegelHaakCtx.dims`). */}
        <Haak
          naam="voorwaardeGhost"
          ctx={{ regel: props.regel, soort: 'toestemming', dims: actieveDimensies() }}
        />
      </ul>
    </Show>
  );
}
