// DE OPEN-STAND VAN EEN VOUWBLOK MET EEN STANDAARDSTAND.
//
// Twee blokken in de kaartbody werken zo: de ledenlijst van een collectie
// (`leden.tsx`, sleutel `coll:<iri>`) en het "gebruikt door"-blok
// (`terugverwijzingen.tsx`, sleutel `usedby:<iri>`). Ze verschillen van elke
// andere <details> in de viewer doordat hun STARTSTAND van de data afhangt:
// `refListCollapsed(n)` zegt dat een korte lijst vanzelf openstaat en een lange
// vanzelf dicht.
//
// Er zijn dus DRIE dingen te onderscheiden, en dat is de hele reden dat deze
// module bestaat:
//
//   1. de lezer zei er niets over  -> de standaard beslist;
//   2. de lezer zette hem OPEN     -> open, ook als de standaard dicht zegt;
//   3. de lezer klapte hem DICHT   -> dicht, ook als de standaard open zegt.
//
// WAT ER MIS WAS (fixronde 1, dt3 lane-toevoegfocus). Geval 3 stond nergens. De
// bewaarde open-stand (`stores/openstand.ts`) noemt per definitie alleen wat
// OPEN stond — zo deed `restoreListUi` in de bevroren viewer het ook: hij opende
// en klapte nooit dicht. De expliciete sluiting leefde daarom in een
// component-lokaal signaal, en dat overleeft geen hermontage. Na een "+
// toestemming" wordt de kaart gericht herbouwd, de component opnieuw gemaakt,
// en dan won de standaard weer: een blok dat de lezer zojuist had dichtgeklapt
// stond ineens weer open. Gemeten in `test/e2e/gevallen/toevoegfocus.mjs`:
// `usedby:…set-1: false → true`, `coll:…gegevens-1: false → true` (tweemaal).
//
// DE OPLOSSING is niet "ook de sluiting bewaren" maar "de keuze van deze SESSIE
// buiten de component leggen": `vluchtigeStand` in de open-stand-administratie
// draagt hem, driestandig, onder dezelfde padsleutel. Vluchtig en niet bewaard,
// om precies de reden die de bevroren viewer ook had — een lijst die vandaag
// kort is kan morgen lang zijn, en dan is "dicht" van gisteren geen uitspraak
// meer over dezelfde lijst. Binnen de sessie is de lijst wél dezelfde, en dan
// telt de keuze.
//
// EN EEN BLOK ZONDER ADRES houdt zijn eigen signaal. Een anonieme collectie
// heeft geen IRI en dus geen sleutel; die kan zijn keuze nergens neerleggen, en
// een gedeelde administratie zonder sleutel zou hem aan de stand van een ánder
// blok vastknopen. Hij gedraagt zich dan precies zoals vóór deze ronde.
import { createSignal } from 'solid-js';
import { vluchtigeStand, zetRijOpen } from '../../stores/openstand.js';

export interface Vouwstand {
  /** Wat de lezer zelf koos, of `null` — dan beslist de standaardstand. */
  handmatig: () => boolean | null;
  /** De lezer wisselde dit blok. Aanroepen vanuit `onToggle`. */
  onthoud: (open: boolean) => void;
}

/** `sleutel` is een getter: de IRI van het blok komt uit props en kan tussen twee
 *  renders van waarde wisselen. */
export function vouwstand(sleutel: () => string): Vouwstand {
  const [lokaal, zetLokaal] = createSignal<boolean | null>(null);
  return {
    handmatig: () => (sleutel() ? vluchtigeStand(sleutel()) : lokaal()),
    onthoud: (open: boolean) => {
      if (sleutel()) zetRijOpen(sleutel(), open); else zetLokaal(open);
    },
  };
}
