// Instap van de nieuwe app: URL lezen, dan mounten.
//
// De volgorde telt. leesUitUrl() zet ook de taal in de modellaag (i18n.js), en
// parse.js leest die instelling voor zijn labelvoorkeur — dus vóór de eerste
// render, precies zoals de bevroren viewer het deed.
//
// De twee smoke-schillen van deeltraject 1 (#model-smoke/#worker-smoke) zijn
// hier vervallen: de app laadt nu een echt corpus via dezelfde keten
// (Vite -> TS -> Solid -> module-worker). De worker-poort van deeltraject 4
// leest dat af aan data-motor op de statusregel; zie tools/worker-smoke.mjs.
import { render } from 'solid-js/web';
import { App } from './app.jsx';
import { registreerStandaarden } from './model-registers.js';
import { leesUitUrl } from './stores/weergave.js';
import './app.css';

// Vóór leesUitUrl, net als in de bevroren viewer: de registraties staan daar op
// moduleniveau (doc.js r.151/156) en dus vóór setLang en vóór de eerste render.
registreerStandaarden();
leesUitUrl(location.search);
render(() => <App />, document.getElementById('app')!);
