// DE BEWERKCHROME-GRENS: de knop die de bewerkstand aanzet, en de dynamische
// import die de hele bewerklaag pas dán binnenhaalt.
//
// DIT BESTAND ZIT IN DE LEESCHUNK. Alles wat het statisch importeert dus ook —
// vandaar dat er geen enkele verwijzing naar `stores/bewerk.js`, `model/edit.js`
// of `ui/bewerk/*` in staat behalve het mountpunt (`ui/bewerk/haken.tsx`, dat
// zelf niets uit de bewerklaag haalt) en de ÉNE `import()` hieronder.
// `stores/lazy-grens.test.ts` bewaakt dat mechanisch; de bundelmeting in het
// report bewijst het aan de gebouwde app.
//
// WAAROM DE KNOP EAGER IS EN DE REST NIET. De knop is chrome: hij staat er
// altijd, ook voor een lezer die nooit gaat bewerken. Wat erachter hangt — de
// mutatiekern, de serialisatielaag, de velden, de stroken — is voor die lezer
// dode code. De grens loopt daarom precies hier: één knop en één `import()`
// aan de leeskant, alles wat werkelijk bewerkt aan de andere.
//
// GEDRAGSBRON: `setEditMode`/`bevestigEditMode` en de potloodknop in de topbalk
// van de bevroren viewer (doc.js). Wat hier ANDERS is: daar bestond de
// bewerkcode altijd al, dus was aanzetten een vlag omzetten. Hier is het een
// LADING, en dus iets dat kan mislukken (een netwerkfout op de chunk). Die
// derde uitkomst heeft de bevroren viewer niet en krijgt hier dus een eigen
// melding en een eigen bodyklasse.
import { createEffect, createSignal, For, onCleanup, onMount, Show } from 'solid-js';
import { Dynamic } from 'solid-js/web';
import type { JSX } from 'solid-js';
import { tekst, weergave, zetMelding, zetWeergave } from '../../stores/weergave.js';
import { bewerkbron, bronRijen, maakBewerkbaar } from '../../stores/bronbeheer.js';
import type { BronBewerk } from '../../stores/bronbeheer.js';
import { bronnenOpen, zetBronnenOpen } from './bronnen.jsx';
import { weigergrond, weigergrondSleutel } from './bronnen-acties.jsx';
import { bronkeuze, zetBronkeuze } from '../bewerk/haken.jsx';

/** Wat de bewerklaag naar de leeskant terugmeldt. Structureel getypeerd: dit
 *  bestand mag `ui/bewerk/laag.tsx` niet statisch kennen. */
export interface Bewerklaag {
  /** De chrome van de bewerkstand: undo/redo, het aanbod, de meldingen. */
  Chrome: () => JSX.Element;
  /** De schakelaar van de mutatiekern. `false` = de stand kon niet aan (geen
   *  bewerkbron); de laag heeft dan zelf het aanbod geopend. */
  zetEditMode: (aan: boolean, opties?: { bevestig?: boolean }) => boolean;
}

const [laag, zetLaag] = createSignal<Bewerklaag | null>(null);
// DE BRONKIEZER-MODAL: open of dicht. Op moduleniveau, net als de andere standen
// hier, want `schakelBewerkstand` is een losse functie en geen component.
const [bronkiezerOpen, zetBronkiezerOpen] = createSignal(false);
const [laden, zetLaden] = createSignal(false);
const [mislukt, zetMislukt] = createSignal(false);

/** Toont het bronnenpaneel zijn BEWERKVORM? In de bewerkstand, en zolang het
 *  aanbod om een bewerkbron vraagt (`bronkeuze`, zie ui/bewerk/haken.tsx voor
 *  waarom die vlag dáár woont en niet hier). */
export const bronpaneelBewerkt = (): boolean => weergave.editMode || bronkeuze();

export { bronkiezerOpen, laag, mislukt };

/** De modal openen. Apart van het signaal, zodat de reden bij de handeling
 *  staat: dit is de enige plek waar hij vanzelf opengaat. */
function openBronkiezer(): void { zetBronkiezerOpen(true); }

// ÉÉN belofte voor de hele sessie: twee klikken op de knop mogen niet twee
// ladingen starten, en na een geslaagde lading is dit een resolved promise die
// niets meer over de lijn haalt.
let lading: Promise<Bewerklaag | null> | null = null;

/** DE ENIGE DYNAMISCHE IMPORT VAN DE BEWERKLAAG. Alles wat bewerkt hangt achter
 *  `ui/bewerk/laag.tsx`; die module registreert bij het laden zijn haken op het
 *  mountpunt, zodat kaarten en rijen die al op het scherm staan meteen hun
 *  affordances krijgen. */
export function laadBewerklaag(): Promise<Bewerklaag | null> {
  if (lading) return lading;
  zetLaden(true);
  lading = import('../bewerk/laag.jsx')
    .then((mod) => mod.laad())
    .then((l: Bewerklaag) => {
      zetLaag(() => l);
      zetMislukt(false);
      return l;
    })
    .catch((e: unknown) => {
      // EEN MISLUKTE LADING IS EEN ZICHTBARE TOESTAND, geen stille no-op. De
      // lezer klikte op "Bewerken" en er gebeurde niets; zonder melding is de
      // enige conclusie die hij kan trekken dat de knop kapot is. `lading` gaat
      // terug op null zodat een tweede klik het opnieuw probeert — een
      // netwerkfout is meestal tijdelijk.
      lading = null;
      zetMislukt(true);
      zetMelding('edit.ladingMislukt', {
        fout: e instanceof Error ? e.message : String(e),
      });
      return null;
    })
    .finally(() => zetLaden(false));
  return lading;
}

/** Testhaak: de sessie terug naar "nog nooit geladen". In de echte app bestaat
 *  dit moment niet — een geladen chunk gaat niet meer weg. */
export function _herstelVoorTest(): void {
  lading = null;
  zetLaag(null);
  zetLaden(false);
  zetMislukt(false);
  zetBronkeuze(false);
}

/** De bewerkstand omzetten. AAN gaat via de lading; UIT kan altijd, ook als de
 *  laag er (nog) niet is — dan staat de stand alleen in de URL en is er niets
 *  om af te schakelen behalve de vlag zelf. */
export async function schakelBewerkstand(aan?: boolean): Promise<boolean> {
  const wil = aan === undefined ? !weergave.editMode : !!aan;
  if (!wil) {
    const l = laag();
    if (l) l.zetEditMode(false);
    // ZONDER LAAG SCHAKELT DE VLAG ZELF (review I-2). Hier stond alleen de
    // regel hierboven, en dan was UIT een no-op zolang er niets geladen was —
    // wat de doc-regel hierboven nu juist uitsluit.
    //
    // Het is geen theoretisch geval: `?edit=1` zet `weergave.editMode` in
    // deeltraject 2, vóór de lading. Mislukt de chunk (de `catch` in
    // `laadBewerklaag`), dan blijft de vlag true, blijven `body.edit-mode` én
    // `body.bewerkstand-mislukte-lading` staan, meldt `edit.ladingMislukt` zich
    // — en de knop staat `aria-pressed="true"` terwijl klikken niets doet. De
    // lezer zit dan vast tot hij de pagina herlaadt.
    else zetWeergave({ editMode: false });
    return false;
  }
  // EERST EEN BEWERKBRON, DAN PAS DE LAAG (herontwerp 9 sep 2026, eigenaar:
  // "als je dat klikt zonder dat een bron bewerkbaar is krijg je een modal
  // waarin je de te bewerken bron kan kiezen; als er meer dan 1 is").
  //
  // Tot vandaag ging deze klik altijd eerst de bewerklaag halen, die dan
  // weigerde en een AANBOD in beeld zette waar de lezer zelf een slotje moest
  // vinden — precies de route die de eigenaar niet vond. Nu wordt de vraag hier
  // gesteld, vóór de lading, met de drie antwoorden die er zijn:
  //   0 bronnen  — er valt niets te kiezen; de laag toont zijn aanbod met de
  //                reden (dat is de enige stand waarin dat aanbod nog dient).
  //   1 bron     — geen vraag, want er is maar één antwoord: die bron wordt de
  //                bewerkbron. Een modal met één knop is een dialoog die de
  //                lezer laat bevestigen wat hij al gezegd heeft.
  //   >1 bronnen — de modal.
  if (!bewerkbron()) {
    const lijst = kiesbareBronnen();
    if (lijst.length > 1) { openBronkiezer(); return false; }
    if (lijst.length === 1) await maakBewerkbaar(lijst[0]);
    else {
      // EN DE VIERDE UITKOMST, die tot nu toe ZWEEG (kruisbevinding
      // lane/release-basis, browsermatrix dt4): er zijn wél bronnen, maar geen
      // ervan kán een bewerkbron worden. Zonder OPFS is dat de hele browser —
      // Safari in privémodus, een oude Firefox — en dan weigerde de knop
      // correct maar zonder één woord: `aria-pressed` bleef "false", de stand
      // ging niet aan, en de lezer bleef klikken. De reden stond wél in de
      // tooltip van elk ✎ in het bronnenpaneel, dus achter twee handelingen die
      // niemand doet als hij niet wéét dat er iets mis is.
      const reden = geenBewerkbronReden();
      if (reden) { zetMelding(reden); return false; }
    }
  }
  const l = await laadBewerklaag();
  if (!l) return false;
  const gelukt = l.zetEditMode(true);
  // DE KLIK OPENT HET BRONNENPANEEL als de stand niet aan kon: de laag heeft dan
  // het aanbod gezet ("kies of maak een bewerkbron"), en die keuze staat in dat
  // paneel. Hier en niet in de laag zelf, want dit hoort bij de HANDELING van de
  // lezer — het boot-pad (?edit=1) zet hetzelfde aanbod maar hoort de pagina
  // niet ongevraagd open te klappen voor iemand die alleen een link volgde.
  if (!gelukt && !bronnenOpen()) zetBronnenOpen(true);
  return gelukt;
}

/** De bronnen waaruit een bewerkbron te kiezen valt: de BESTANDSbronnen, en
 *  alleen die er ook eentje kunnen worden (geen lokale opslag of een bron die
 *  niet gelezen kon worden — dan zou de kopie leeg zijn).
 *
 *  HET ENDPOINT STAAT ER NIET BIJ, met reden: het endpoint bewerkbaar maken
 *  vraagt een update-URL, en die valt niet af te leiden (zie
 *  `updateUrlVoorstel`). Dat is een handeling met een invoerveld, en die hoort
 *  in het bronnenpaneel te blijven — een modal die om een URL vraagt is geen
 *  keuzelijst meer. */
/** WAAROM ER NIETS TE KIEZEN VALT — als i18n-sleutel, of null.
 *
 *  Alleen zinvol als er WÉL bronnen zijn: een leeg document heeft geen reden
 *  nodig, en daar hoort het aanbod van de bewerklaag ("kies of maak een
 *  bewerkbron") nog steeds thuis. Is elke kandidaat geweigerd, dan is er één
 *  gedeelde reden en die is te melden. `src.opfsUit` wint van `src.lockFout`:
 *  hij geldt voor de hele browser, en zou anders verzwegen worden door één bron
 *  die toevallig ook niet te lezen was. */
export function geenBewerkbronReden(): string | null {
  const kandidaten = bronRijen().filter((b) => !b.fromSparql && !b.vocab);
  if (!kandidaten.length) return null;
  const gronden = kandidaten.map((b) => weigergrondSleutel(b));
  if (gronden.some((g) => g === null)) return null;
  return gronden.includes('src.opfsUit') ? 'src.opfsUit' : gronden[0];
}

export function kiesbareBronnen(): BronBewerk[] {
  // `!b.vocab`: de ondersteunende bronnen (profielvocabulaire, TOOI-labels)
  // laadt de app zelf mee en zijn niet van de lezer — ze bewerkbaar aanbieden
  // zou een keuze zijn die bij de volgende lading weer wordt overschreven.
  return bronRijen().filter((b) => !b.fromSparql && !b.vocab && !weigergrond(b));
}

/** DE KNOP IN DE KOP. `aria-pressed` en niet twee knoppen: dit is één
 *  schakelaar met twee standen, en een schermlezer hoort dat te horen. De
 *  tooltip zegt wat de klik DOET (aanzetten/uitzetten), het label zegt waar de
 *  knop over gaat — dezelfde verdeling als in de bevroren viewer. */
export function Bewerkknop(): JSX.Element {
  return (
    <button
      class="btn bewerk-knop"
      id="btn-bewerken"
      type="button"
      aria-pressed={weergave.editMode ? 'true' : 'false'}
      // De lading duurt in de praktijk een tik; een `aria-busy` erbij zegt het
      // hardop voor wie de knop niet ziet verspringen.
      aria-busy={laden() ? 'true' : undefined}
      title={tekst(weergave.editMode ? 'edit.uit' : 'edit.aan')}
      // HET LABEL BLIJFT, HET WOORD VERDWIJNT (herontwerp 9 sep 2026: "Op de
      // topnav wordt 'Bewerken' een edit icoon"). Een icoon zonder toegankelijke
      // naam is voor een schermlezer een knop die "knop" heet; `aria-label`
      // draagt daarom het woord dat er stond, en de tooltip blijft zeggen wat de
      // klik DOET. Het teken zelf is ✎ en geen emoji-potlood: zonder emoji-font
      // blijft van een emoji een leeg blokje over.
      aria-label={tekst('edit.kaart')}
      onClick={() => { void schakelBewerkstand(); }}
    >✎</button>
  );
}

/** DE BRONKIEZER — de modal achter de bewerkknop.
 *
 *  HERONTWERP 9 SEP 2026, eigenaar, letterlijk: "als je dat klikt zonder dat een
 *  bron bewerkbaar is krijg je een modal waarin je de te bewerken bron kan
 *  kiezen; als er meer dan 1 is". Hij vervangt de route die niemand vond: eerst
 *  het bronnenpaneel opendoen, daar het slotje van de juiste bron zoeken, en pas
 *  dan opnieuw op Bewerken klikken.
 *
 *  ÉÉN KEUZE, GEEN BEVESTIGING. Klikken op een bron maakt hem de bewerkbron
 *  (inclusief de lokale kopie) en zet de bewerkstand aan — dezelfde ene klik als
 *  het ✎ in het paneel, en om dezelfde reden: er gaat niets verloren (het
 *  origineel blijft, ↶ gooit de kopie weg). De opmaakverlies-zin staat vooraf in
 *  de tooltip van elke keuze.
 *
 *  TOETSENBORD: bij het openen krijgt de eerste keuze de focus, Tab loopt rond
 *  binnen de dialoog (`aria-modal` belooft dat de rest er niet is, dus dan moet
 *  de focus daar ook niet heen kunnen), en Escape sluit en geeft de focus terug
 *  aan de knop die hem opende.
 *
 *  IN DE ESCAPE-LAAGORDE is dit de BOVENSTE laag: sleep → modal → veld/menu →
 *  invulling-paneel → bronnenpaneel → zijnav. De klasse `bronkiezer-open` op de
 *  body is waar het bronnenpaneel dat aan afleest; op mountvolgorde vertrouwen
 *  zou hier niet kunnen, want deze luisteraar wordt pas geregistreerd als de
 *  modal opengaat — dus ná die van het paneel. */
function Bronkiezer(): JSX.Element {
  let doos: HTMLDivElement | undefined;
  const focusbaar = (): HTMLElement[] =>
    [...(doos?.querySelectorAll<HTMLElement>('button:not([disabled])') ?? [])];

  const sluit = (): void => {
    zetBronkiezerOpen(false);
    if (typeof document !== 'undefined') {
      (document.getElementById('btn-bewerken') as HTMLElement | null)?.focus();
    }
  };
  const kies = (b: BronBewerk): void => {
    zetBronkiezerOpen(false);
    void maakBewerkbaar(b).then(() => schakelBewerkstand(true));
  };

  onMount(() => {
    if (typeof document === 'undefined') return;
    document.body.classList.add('bronkiezer-open');
    focusbaar()[0]?.focus();
    const opToets = (e: KeyboardEvent): void => {
      if (e.key === 'Escape') {
        e.preventDefault();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        else e.stopPropagation();
        sluit();
        return;
      }
      if (e.key !== 'Tab') return;
      const l = focusbaar();
      if (!l.length) return;
      const hier = l.indexOf(document.activeElement as HTMLElement);
      const doel = e.shiftKey
        ? (hier <= 0 ? l.length - 1 : hier - 1)
        : (hier === l.length - 1 ? 0 : hier + 1);
      e.preventDefault();
      l[doel].focus();
    };
    document.addEventListener('keydown', opToets, true);
    onCleanup(() => {
      document.removeEventListener('keydown', opToets, true);
      document.body.classList.remove('bronkiezer-open');
    });
  });

  return (
    <div class="bronkiezer-scherm">
      <div
        class="bronkiezer"
        id="bronkiezer"
        role="dialog"
        aria-modal="true"
        aria-labelledby="bronkiezer-titel"
        ref={doos}
      >
        <h2 class="bronkiezer-titel" id="bronkiezer-titel">{tekst('edit.kiesBron')}</h2>
        <p class="bronkiezer-uitleg muted">{tekst('src.bewerkbronPaneel')}</p>
        <ul class="bronkiezer-lijst">
          <For each={kiesbareBronnen()}>{(b) => (
            <li>
              <button
                type="button"
                class="bronkiezer-keuze"
                title={b.opfs
                  ? tekst('edit.kiesBronKort')
                  : `${tekst('edit.kiesBronKort')} — ${tekst('src.lockWaarschuwing')}`}
                onClick={() => kies(b)}
              >{b.name}</button>
            </li>
          )}</For>
        </ul>
        <button
          type="button"
          class="btn bronkiezer-annuleer"
          onClick={() => sluit()}
        >{tekst('src.lockAnnuleer')}</button>
      </div>
    </div>
  );
}

/** DE CHROME VAN DE BEWERKSTAND. Zolang de laag niet geladen is, staat hier
 *  niets — geen skelet, geen plaatshouder: in de leesstand hoort de pagina er
 *  identiek uit te zien als vóór dit deeltraject.
 *
 *  Ook de BODYKLASSEN hangen hier, want zij horen bij de stand en niet bij de
 *  knop: `edit-mode` is de haak waaraan de bewerk-CSS (hover-dichtheid,
 *  strookruimte) hangt, `bewerkstand-mislukte-lading` die van een lading die
 *  niet doorkwam. Twee gedeelde rijen uit de vertaaltabel; de chrome-helft
 *  ervan staat hier. */
export function Bewerkchrome(): JSX.Element {
  onMount(() => {
    // HET BOOT-PAD: `?edit=1` uit de adresbalk staat al in de weergavestore
    // (deeltraject 2), maar de laag die er iets mee doet is er nog niet. Zonder
    // deze lading zou de pagina in "bewerkstand" staan zonder één affordance.
    //
    // `zetEditMode(true)` EN NIET `bevestigEditMode()`: de lezer heeft in beide
    // gevallen om de bewerkstand gevraagd, dus hoort hij in beide gevallen
    // hetzelfde antwoord te krijgen. Bevestigen alleen zou de stand stil
    // terugzetten bij een corpus zonder bewerkbron — en dan staat er nergens op
    // de pagina meer een route naar een bewerkbron, want de keuzegroep in het
    // bronnenpaneel verschijnt pas in de bewerkvorm. Zo krijgt hij het AANBOD,
    // met de reden erbij.
    if (weergave.editMode) {
      void laadBewerklaag().then((l) => l && l.zetEditMode(true));
    }
  });

  createEffect(() => {
    const b = typeof document === 'undefined' ? null : document.body;
    if (!b) return;
    b.classList.toggle('edit-mode', weergave.editMode);
    b.classList.toggle('bewerkstand-mislukte-lading', mislukt());
  });

  // DE MODAL HANGT HIER en niet bij de knop: `Bewerkchrome` staat in de schil
  // vóór het bronnenpaneel, en staat er altijd — ook als de bewerklaag nooit
  // geladen wordt. De kiezer gaat juist open op het moment dat die laag er nog
  // niet is.
  return (
    <>
      <Show when={bronkiezerOpen()}><Bronkiezer /></Show>
      <Show when={laag()}>{(l) => <Dynamic component={l().Chrome} />}</Show>
    </>
  );
}
