// HOE ÉÉN VERWIJZINGSRIJ LEEST (puur, DOM-vrij).
//
// Deze twee functies stonden tot 16 sep 2026 in `ui/verken/verken-model.ts`,
// het knoopmodel van de RDF-verkenner. Die verkenner is gesloopt
// (eigenaarsbesluit: "Comunica gebruik ik praktisch nooit. Mag weg incl
// functionaliteit in de viewer/editor"), maar hij was niet hun enige afnemer:
// `terugverwijzingen.tsx` — de "gebruikt door N"-regel op elke kaart — leest
// zijn rijen met dezelfde twee functies, en die regel blijft.
//
// De rest van dat bestand ging wél mee: `verkenKnoop` (het knoopmodel met zijn
// twee richtingen) en `waardeTekst` (de literalweergave van de verkenner)
// hadden geen tweede afnemer.
//
// WAAROM t() EN NIET tekst(). De UI-laag gebruikt `tekst()` uit de
// weergavestore, want dat is de reactieve leesplek. Deze module is bewust
// framework-vrij (geen solid-import, node-testbaar zonder store) en haar
// aanroeper maakt de reactiviteit zelf: de rijenlijst in terugverwijzingen.tsx
// wordt in een memo gebouwd die de graafversie leest.
import { localName, t } from '../../model-grens.js';
import type { PredicaatKop, Verwijzing } from '../../model-grens.js';

/** De tekst van één verwijzingsrij: naam (of curie, of "(anoniem)") plus het
 *  predicaat. */
export function refRijTekst(ref: Partial<Verwijzing>): { title: string; pred: string } {
  return {
    title: ref.label || ref.curie || (ref.iri ? localName(ref.iri) : t('anon')),
    pred: predicaatTekst(ref.predicate),
  };
}

/** Het predicaat waarmee verwezen wordt: label plus curie, of alleen de curie
 *  als het label niets toevoegt. */
export function predicaatTekst(p?: Partial<PredicaatKop> | null): string {
  if (!p) return '';
  return p.label && p.label !== p.curie ? `${p.label} (${p.curie})` : (p.curie || '');
}
