// DE KAART — één beleidsstuk, in de leesvorm.
//
// Aanbod, overeenkomst, beleidsset en verzoek zijn ÉÉN kaartvorm (beslissing
// eigenaar, aug 2026): dezelfde schil, dezelfde kopregel, dezelfde chevron. Het
// SOORT spreekt kleur — als accent op de kaart (kantlijn + pil), niet als een
// eigen vorm. Gedragsbron: setSection, offerSection/fillOfferSection en
// fillAgreementPage in de bevroren viewer (viewer-bevroren/assets/doc.js).
//
// PROPS-CONTRACT (voor lane-lijst en latere taken): de kaart krijgt ALLEEN de
// policy uit het model mee plus wat de LIJST over de plaatsing weet (anker,
// open-stand, extra kopelementen). Al het andere leest zij zelf uit de stores —
// dat houdt de kaart bruikbaar in de lijst, op een ?policy=-detailpagina en in
// een testpagina zonder dat de aanroeper state hoeft door te geven.
//
// WAT HIER (NOG) NIET IN ZIT, met opzet: alle bewerk-affordances
// (deeltraject 3). De ⌕-verkenknop staat er sinds de gaten-ronde wél op
// (bevinding C-1).
// `kopExtra` is de haak waaraan de lijst haar kopelementen hangt (de
// versienavigator-chip, de tellingen-als-link) zonder deze component te
// herschrijven.
//
// DE TWEEFASIGE LADING (taak 7) raakt de kaart op één plek: `hydrateer`. Dat is
// een getter die de aanroeper BINNEN de Suspense-grens van deze kaart laat
// lezen — in de praktijk een `createResource` die het detail-CONSTRUCT van deze
// policy ophaalt. Zolang die resource laadt toont de kaart haar skeletregels in
// plaats van een lege body (`cardLoading` in de bevroren viewer); de KOP blijft
// staan. Dat is de Solid-vorm van skelet-dan-hydrateer: geen tikken op de klok,
// maar een toestand.
import { createEffect, createSignal, Show, Suspense } from 'solid-js';
import type { JSX } from 'solid-js';
import { versionNavModel } from '../../model/parse.js';
import { model } from '../../stores/corpus.js';
import { tekst } from '../../stores/weergave.js';
import { PRED, Veld } from '../bewerk/haken.jsx';
import { Chevron, SoortPil, VersieChip } from '../gedeeld/chip.jsx';
import type { Kaartsoort } from '../gedeeld/chip.jsx';
import { KaartBody } from './body-rijen.jsx';
import { ChipRuimte } from './voorwaarde-inhoud.jsx';
import type { ExtraEigenschap } from './body-rijen.jsx';
import { Regels } from './regels.jsx';
import './kaart.css';
import { kopBediening } from '../gedeeld/kopselectie.js';
import { meescrollNaUitklap } from '../gedeeld/meescroll.js';
import { focusAdres, ghostOnthulKlasse, Haak } from '../gedeeld/bewerkhaak.jsx';

export type { Kaartsoort };
export type { ExtraEigenschap };

// --- Het stuk van het weergavemodel dat de kaartfamilie leest ---------------
// De modellaag is (nog) JavaScript; deze typen beschrijven wat parse.js
// oplevert, in de mate waarin de kaart het gebruikt. Ze verhuizen naar
// model-grens.ts zodra de modellaag zelf getypeerd is.

/** Een herkomst-/versieverwijzing (prov:wasDerivedFrom, wasRevisionOf, …). */
export interface Verwijzing {
  iri: string;
  curie?: string | null;
  label?: string | null;
  title?: string | null;
}

/** Een partij of ander verwezen object: label + curie + IRI. */
export interface Partij {
  iri?: string | null;
  curie?: string | null;
  label?: string | null;
  desc?: string;
  anon?: boolean;
}

/** De versie-/geldigheidsgegevens van een policy (readVersionInfo). */
export interface Versie {
  effectiveFrom?: string | null;
  effectiveTo?: string | null;
  revisionOf?: Verwijzing | null;
  supersededBy?: Verwijzing[];
  derivedFrom?: Verwijzing[];
}

/** De actie van een regel. Een permission draagt hem als descriptor, een duty
 *  als kaal label (readDuty) — beide vormen komen hier binnen. */
export type RegelActie = { iri?: string | null; curie?: string | null; label?: string; desc?: string };

/** Een regel: toestemming, verbod of verplichting. */
export interface Regel {
  iri: string | null;
  title?: string | null;
  label?: string | null;
  description?: string | null;
  action?: RegelActie | string | null;
  purpose?: (RegelActie & { operatorWord?: string }) | null;
  targets?: Partij[];
  assignee?: Partij | null;
  informedParty?: Partij | null;
  primarySources?: Verwijzing[];
  constraints?: unknown[];
  refinements?: unknown[];
  duties?: Regel[];
  extraProps?: ExtraEigenschap[];
  kind?: string;
}

/** Eén beleidsstuk zoals buildModel het oplevert. */
export interface Policy {
  iri: string;
  kind?: string;
  curie?: string | null;
  anon?: boolean;
  stub?: boolean;
  isRequest?: boolean;
  title?: string | null;
  description?: string | null;
  identifier?: string | null;
  issued?: string | null;
  profile?: string | null;
  assigner?: Partij | null;
  assignee?: Partij | null;
  offers?: string[];
  requests?: Verwijzing[];
  asksFor?: Verwijzing[];
  datasetIri?: string | null;
  permissions?: Regel[];
  prohibitions?: Regel[];
  obligations?: Regel[];
  version?: Versie | null;
  extraProps?: ExtraEigenschap[];
}

/** De kaartsoort uit het model. Een odrl:Request is qua weergave een set
 *  (beleid zonder aanbod-/overeenkomst-rol), maar hij draagt een eigen pil en
 *  een eigen sectie — generieke ODRL-kernkennis, geen profielkennis. */
export function soortVan(pol: Policy): Kaartsoort {
  if (pol.kind === 'offer') return 'offer';
  if (pol.kind === 'agreement') return 'agreement';
  return pol.isRequest ? 'request' : 'set';
}

// De drie CSS-haken per soort, letterlijk die van doc.css: de kaartschil met
// haar accentkleur (--card-accent), de kopbalk en de titelmaat. Set en verzoek
// delen de set-kaart; de overeenkomst heeft haar eigen groene accent.
const KAART_KLASSE: Record<Kaartsoort, string> = {
  offer: 'offer-group',
  agreement: 'agr-group',
  set: 'offer-group set-card',
  request: 'offer-group set-card',
};
const KOP_KLASSE: Record<Kaartsoort, string> = {
  offer: 'offer-summary', agreement: 'agr-summary',
  set: 'offer-summary', request: 'offer-summary',
};
const TITEL_KLASSE: Record<Kaartsoort, string> = {
  offer: 'offer-title', agreement: 'agr-title',
  set: 'offer-title', request: 'offer-title',
};

/** Het aantal regels op een kaart — verplichtingen, toestemmingen én verboden,
 *  net als de `nOps`-telling in de bevroren viewer. */
export function telRegels(pol: Policy): number {
  return (pol.obligations || []).length + (pol.permissions || []).length
    + (pol.prohibitions || []).length;
}

/** De levensfase van de GETOONDE versie van deze policy, of null als zij
 *  buiten een versiecontainer valt. */
export function versieStatus(pol: Policy): string | null {
  if (pol.anon || !pol.iri) return null;
  const nm = versionNavModel(model(), pol.iri) as { shown?: { status?: string } } | null;
  return (nm && nm.shown && nm.shown.status) || null;
}

/** Het afnemer-label dat naast de titel van een overeenkomst hoort, of null
 *  als de titel hem al draagt (agreementGroup in de bevroren viewer). */
export function afnemerNaast(pol: Policy): string | null {
  const naam = pol.assignee && pol.assignee.label;
  if (!naam) return null;
  return (pol.title || '').includes(naam) ? null : naam;
}

export interface KaartProps {
  /** De policy uit het model (model().sets/offers/agreements). */
  pol: Policy;
  /** Overschrijft de afgeleide kaartsoort (een stub-versie van een besluit
   *  weet zijn soort van zijn container, niet van zichzelf). */
  soort?: Kaartsoort;
  /** Het anker-id waar de lijst en de deeplinks naartoe springen. */
  anker?: string;
  /** Start de kaart uitgeklapt? De lijst beslist dat (deeplink, onthouden
   *  open-stand); de kaart heeft er geen eigen mening over. */
  open?: boolean;
  /** De compacte verzoek-vorm: kenmerk, datum en indiener als subtitel, geen
   *  regeltelling in de kop. */
  compact?: boolean;
  /** De detailvorm (?policy=): op een overeenkomst drie velden méér dan in de
   *  lijst — zie agreementRijen. */
  detail?: boolean;
  /** Kopelementen van latere taken (versienavigator, tellingen-als-link),
   *  vóór de chevron. */
  kopExtra?: JSX.Element;
  /** LUI: bouw body en regels pas bij de eerste uitklap. In een lijst van
   *  1.392 kaarten is de kop het enige dat altijd nodig is; de rest is werk
   *  voor kaarten die niemand opent. Zonder `lazy` staat de body er meteen
   *  (de <details> verbergt hem dan), zoals op een detailpagina. */
  lazy?: boolean;
  /** De kaart klapte open of dicht. De LIJST onthoudt die stand (per
   *  bronnencorpus); de kaart bewaart niets zelf. */
  onKlap?: (open: boolean) => void;
  /** Wordt BINNEN de Suspense-grens van deze kaart uitgelezen: laadt de
   *  resource die hij aanspreekt, dan toont de body skeletregels in plaats van
   *  een lege body. Zie de kop van dit bestand. De getter hoort NIETS
   *  renderbaars terug te geven (een resource die op `null` uitkomt) — hij is
   *  er om gelezen te worden, niet om iets te tonen. */
  hydrateer?: () => unknown;
}

/** De laadweergave in een kaart-body terwijl haar detail-CONSTRUCT loopt: een
 *  paar regelbalkjes in plaats van een halve kaartenlijst, met de melding
 *  eronder voor wie hem niet ziet (`cardLoading`/`skeletonLines` in de bevroren
 *  viewer). */
export function KaartLaden(): JSX.Element {
  return (
    <div class="card-loading">
      <span class="sr-only" role="status" aria-live="polite">{tekst('load.cardDetail')}</span>
      <div class="skel-lines" aria-hidden="true">
        <span class="skel skel-line skel-v0" />
        <span class="skel skel-line skel-v1" />
        <span class="skel skel-line skel-v2" />
      </div>
    </div>
  );
}

export function Kaart(props: KaartProps): JSX.Element {
  const soort = () => props.soort ?? soortVan(props.pol);
  const aantal = () => telRegels(props.pol);
  // Eenmaal gebouwd blijft gebouwd: dichtklappen gooit de body niet weg, zodat
  // opnieuw openen niets kost. Dat is ook wat de bevroren viewer doet (`built`
  // in setsCardsView blijft staan tot de kaart hervuld wordt).
  const [gebouwd, zetGebouwd] = createSignal(!props.lazy || !!props.open);
  createEffect(() => { if (props.open) zetGebouwd(true); });
  return (
    // `ghostOnthulKlasse()`: DE ONTHULLER VAN DE GHOSTS ZIT OP DEZE WORTEL
    // (review I-1). Alles wat binnen deze kaart aan schimmen staat — de
    // regel-ghost, de overeenkomst-ghost — is gedimd tot de muis boven de KAART
    // komt of de focus erbinnen valt. Op een omhulsel om de ghost zelf betekende
    // dezelfde CSS-regel "de ghost onthult zichzelf", en dat is onvindbaarheid in
    // plaats van dichtheid. In de kijkstand staat de klasse er niet.
    <details
      class={KAART_KLASSE[soort()] + ghostOnthulKlasse()}
      id={props.anker}
      data-iri={props.pol.iri || undefined}
      // Het data-ref-contract: elke kaart is adresseerbaar op de IRI van haar
      // knoop — dat is waarop het invulling-paneel en de sprongen mikken.
      data-ref={props.pol.iri || undefined}
      open={props.open}
      onToggle={(e) => {
        const aan = e.currentTarget.open;
        if (aan) zetGebouwd(true);
        props.onKlap?.(aan);
        // MEESCROLLEN BIJ UITKLAPPEN: klap je onderin het scherm een kaart open,
        // dan valt de nieuwe inhoud onder de vouw. De pagina schuift dan mee —
        // maar alléén als deze stand van de LEZER komt: de onthouden open-stand,
        // een deeplink en het herstel na een modelherbouw vuren hetzelfde
        // toggle-event, en die horen de pagina te laten staan. Die poort zit in
        // meescroll.ts; hier staat alleen de aanroep. Zie daar ook de grens met
        // het scrollanker van de lijst.
        if (aan) meescrollNaUitklap(e.currentTarget);
      }}
    >
      <summary class={KOP_KLASSE[soort()]} {...kopBediening()}>
        <SoortPil soort={soort()} />
        {/* FAMILIES 3 EN 4 van de kopieerveeg (9 sep 2026): tussen de soortpil en
            de kaarttitel stond alleen de `gap: 10px` van `.offer-summary`/
            `.agr-summary`, en een gap komt niet in het klembord — geplakt las de
            kop als "AanbodAanbod BRF-gegevens". De ruimte gaat in kaart.css uit
            de stroom, zodat de 10px 10px blijft. */}
        <ChipRuimte />
        {/* DE TITEL is het eerste ✎ van de kaart (fase C taak 5, `titelVeld`).
            Het veld zit BINNEN de titel-span, niet eromheen: de klasse draagt
            de lettergrootte van de kop, en een bewerkvorm die buiten die span
            valt zou in de bewerkstand ineens op body-grootte staan.

            `dragendPred` kiest tussen dct:title en rdfs:label — schrijven naar
            het eerste terwijl de waarde uit het tweede komt, laat de bewerking
            stilzwijgend niets doen. Een ANONIEME policy heeft geen IRI maar wel
            een term; dat is waar de mutatie op landt. */}
        <span class={TITEL_KLASSE[soort()]}>
          <Veld spec={{
            term: props.pol.anon ? (props.pol as { term?: unknown }).term : props.pol.iri,
            soort: 'tekst',
            preds: PRED.TITEL,
            waarde: props.pol.title,
            // DE HINT VAN EEN NAAMLOZE KAART (eigenaarsbevinding 9 sep 2026,
            // tweede ronde). Sinds `createSkeleton` geen `dct:title "Nieuw
            // aanbod"` meer schrijft, is een verse kaart écht titelloos: de kop
            // toont dan de terugval van `labelFor` (de localName, "aanbod"), en
            // het INVOERVELD staat leeg met deze hint. Zie `TekstVeld` voor
            // waarom die twee uit elkaar lopen.
            hint: tekst('edit.hintTitel'),
            // "+ nieuw beleid" en "+ overeenkomst op dit aanbod" maken een KAART;
            // ook daar hoort de cursor in de titel te landen (eigenaarsbesluit
            // 8 sep 2026). Dezelfde adresvorm als bij een regelrij.
            focusSleutel: focusAdres(props.pol.anon
              ? (props.pol as { term?: unknown }).term : props.pol.iri),
          }}
          >{props.pol.title}</Veld>
        </span>
        {/* DE NODE-ID VAN DE KAART (eigenaarsverzoek 9 sep 2026, letterlijk:
            "Ik kan de node-id niet editen").

            ALLEEN IN DE BEWERKSTAND, en dat is geen halve maatregel maar de
            pariteitsgrens: de bevroren viewer draagt geen IRI op de kaartkop, en
            een chip die er in de LEESweergave bij komt zou een gelabelde
            verbetering zijn die niemand vroeg. `Veld` rendert in de kijkstand
            letterlijk zijn kinderen, en die zijn hier leeg — dus daar verandert
            er geen pixel. In de bewerkstand staat er de curie (of de volle IRI
            als die niet terugleest) met zijn ✎ ernaast.

            `vorm: 'knoopIri'` en GEEN `preds`: een IRI is de naam van de knoop
            en geen waarde erop. Zie `VeldSpec.vorm` en `hernoemKnoop`. */}
        {/* EEN ANONIEME KAART DRAAGT DEZELFDE CHIP, LEEG (eigenaarsrichting
            9 sep 2026: "En hoe we bestaande nodes kunnen 'namen' natuurlijk").
            Zij stond hier achter `!props.pol.anon`, en daarmee was de enige
            route naar een herbruikbare knoop juist op de kaarten dicht die hem
            nodig hebben: een blank-node-policy is buiten dit document niet aan
            te wijzen. De bewerklaag maakt van de lege chip een "geef een naam
            (IRI)"-affordance (`KnoopIriVeld`); in de LEESstand rendert `Veld`
            letterlijk zijn kinderen — hier geen — dus daar verandert er nog
            steeds geen pixel. */}
        <Show when={props.pol.anon ? (props.pol as { term?: unknown }).term : props.pol.iri}>
          <Veld spec={{
            term: props.pol.anon ? (props.pol as { term?: unknown }).term : props.pol.iri,
            soort: 'iri',
            preds: [],
            vorm: 'knoopIri',
            iri: props.pol.anon ? null : props.pol.iri,
          }}
          />
        </Show>
        {/* De AFNEMER naast de titel van een overeenkomst: op een lijst van
            1.392 besluiten is dat het veld waarop je ze uit elkaar houdt
            (agr-assignee in de bevroren viewer) — maar ALLEEN als de titel hem
            niet al draagt. Sinds de titelopschoning ÍS de besluittitel vaak de
            afnemersnaam, en dan zou de kopregel hem verdubbelen. Bewust het
            LABEL en niet de curie: een curie staat nooit in een titel, dus een
            terugval daarop zou de toets betekenisloos maken. */}
        <Show when={soort() === 'agreement' && afnemerNaast(props.pol)}>{(naam) => (
          <><ChipRuimte /><span class="agr-assignee muted">{naam()}</span></>
        )}</Show>
        {/* Vanaf hier de KOPSTAART: statuschip, ⌕, telling, lijstextra.
            Elk krijgt zijn eigen kopieerbare spatie ervoor — zij staan in
            de `.offer-summary`/`.agr-summary`-flexrij, waar alleen een
            `gap: 10px` ze scheidde. Zie de kopieerveeg in kaart.css. */}
        <ChipRuimte />
        <VersieChip status={versieStatus(props.pol)} />
        {/* HET ⌕ VAN DE KAART (bevinding C-1): tussen de statuschip en de
            regeltelling, precies waar de bevroren viewer hem zet — op de
            aanbodkop (doc.js r.7893), de besluitkop (r.7024) en de setkop
            (r.8468). Een ANONIEME policy heeft geen adres en dus geen ⌕:
            `verkenBtn(pol.anon ? pol.term : pol.iri)` levert daar null, en
            <VerkenKnop> doet hetzelfde. */}
        <ChipRuimte />
        <Show when={!props.compact && aantal()}>
          <ChipRuimte />
          <span class="op-sum muted">{tekst('rules.count', { n: aantal() })}</span>
        </Show>
        {props.kopExtra}
        {/* DE ACTIESTROOK VAN DE KAART (⠿ uit, ✎, ⧉, ✕), ná de kopelementen
            van de lijst en vóór de chevron. Eén regel, en hij staat leeg zolang
            de bewerklaag niet geladen is — zie `ui/gedeeld/bewerkhaak.tsx`. */}
        <Haak naam="kaartkop" ctx={{ pol: props.pol, soort: soort() }} />
        <Chevron />
      </summary>
      <Show when={gebouwd()}>
        <Suspense fallback={<KaartLaden />}>
          {/* De hydratie-poort: leest de aanroeper hier een ladende resource,
              dan valt deze grens terug op de skeletregels — de kop blijft
              staan, de body vult zich zodra het detail binnen is. */}
          {props.hydrateer?.() as JSX.Element}
          <KaartBody pol={props.pol} soort={soort()} compact={props.compact} detail={props.detail} />
          <Regels pol={props.pol} soort={soort()} />
        </Suspense>
      </Show>
    </details>
  );
}
