// Taalkiezer rechtsboven (audit-punt B16), sinds 14 sep 2026 een DROPDOWN.
//
// Gedragsbron: applyChrome + switchLang in de bevroren viewer. Wat blijft: de
// keuze staat in `?lang=` in de adresbalk — óók voor de voorkeurstaal, zodat
// een gedeelde link de keuze draagt — het documenttaal-attribuut volgt, en er
// gaat een scrollanker vast vóór de wissel.
//
// WAT VERANDERT IS DE VORM. Tot vandaag stonden hier twee knoppen met de vaste
// labels NL en EN en een aria-pressed-stand. Dat werkt voor precies twee talen;
// de taalvoorkeur is sinds de eigenaarsgo van 14 sep een BUILDINSTELLING
// (TAALVOORKEUR in model/i18n.js) en kan er drie of vijf bevatten, en dan is
// een knoppenrij in de kop geen vorm meer.
//
// EEN NATIVE `<select>`, en met opzet geen eigen popover: label, toetsenbord,
// typeahead, aria-stand en de mobiele wielkiezer komen dan van de browser. De
// optietekst is de naam van de taal IN DIE TAAL ZELF (Nederlands / English) —
// die komt uit `taalNaam()` en niet uit de stringtabel, want er valt niets aan
// te vertalen. De codes NL/EN waren als optietekst geen optie meer: met drie
// talen leest een lijst van tweeletterige codes als een foutmelding.
//
// Wat vervalt: het OPEN-STAND-deel van de capture/restore-machinerie eromheen.
// De oude wissel bouwde model én DOM opnieuw op en moest daarom eerst de open
// kaarten en de filterteksten vastleggen. Hier is de taal een storewaarde;
// alleen de knopen die haar lezen lopen opnieuw, en alles wat openstond blijft
// openstaan.
//
// WAT NIET VERVALT: de SCROLLPOSITIE. Die is een eigenschap van het venster en
// overleeft niets — het model wordt opnieuw gebouwd, de lijst is even leeg, de
// pagina krimpt tot vensterhoogte en de browser knijpt scrollY tot 0 af. De
// bevroren viewer zet daarom een scrollanker terug (switchLang → captureListUi/
// settleScrollAnchor, doc.js r.1422-1427); dat doet de dropdown hieronder ook,
// via `houdAnkerVast`. Het anker wordt pas losgelaten als het nieuwe model
// binnen is — zie `src/ui/lijst/scrollanker.ts`.
import { For } from 'solid-js';
import { LANGS, taalNaam } from '../../model/i18n.js';
import { type Taal, tekst, weergave, zetWeergave } from '../../stores/weergave.js';
import { houdAnkerVast } from '../lijst/scrollanker.js';

export function Taalkiezer() {
  const talen = LANGS as Taal[];
  return (
    <select
      class="lang-select"
      id="taalkiezer"
      aria-label={tekst('lang.aria')}
      value={weergave.lang}
      onChange={(e) => {
        const gekozen = e.currentTarget.value as Taal;
        if (gekozen === weergave.lang) return;
        houdAnkerVast();
        zetWeergave({ lang: gekozen });
      }}
    >
      <For each={talen}>{(l) => (
        <option value={l} selected={l === weergave.lang}>{taalNaam(l)}</option>
      )}</For>
    </select>
  );
}
