// TERUGVERWIJZINGEN — "gebruikt door N", met uitklap.
//
// VERBETERING 4 (besluit 4 sep). Een RDF-graaf kent maar één richting: het
// tripel zegt dat A naar B verwijst, en wie B leest ziet dat niet. De oude
// viewer loste dat per geval op — "Overeenkomsten op dit aanbod" op een
// Offer-kaart, "beslist in" op een verzoek — telkens met eigen modelwerk voor
// één predicaat. Deze widget doet het GENERIEK: bij een knoop staat één regel
// met de telling van alles wat naar hem verwijst, en die klapt uit naar de
// verwijzers met het predicaat waarmee ze het doen.
//
// DE BIJZONDERE VELDEN BLIJVEN. Dit vervangt de eigen regels niet: "Vult aanbod
// in" en "beslist in" zeggen wát de relatie betekent, en dat is meer dan een
// telling. Deze regel is de rest — de verwijzingen waar geen eigen veld voor
// is, en op een druk bezochte knoop het antwoord op "wie gebruikt dit
// eigenlijk?".
//
// Gegevensbron: incomingRefs/incomingRefCount in src/model/parse.js. Dezelfde
// functies voedden het bovenste richtingblok van de RDF-verkenner; die is op
// 16 sep 2026 gesloopt, en deze regel is wat ervan overblijft — per ding in het
// document in plaats van per knoop in een aparte stand.
//
// LAZY EN GECHUNKT, om dezelfde reden als daar: de TELLING is een goedkope
// indexafdaling, maar `incomingRefs` bouwt per verwijzing een label en dat is
// op een knoop met 1.392 verwijzers (BRP) te duur voor een blok dat dicht
// staat. De lijst wordt dus pas gebouwd als het blok open gaat, daarna per
// CARD_CHUNK_SIZE getoond, met boven REF_LIST_INLINE_MAX een filterveld. Tot en
// met die drempel staat het blok meteen open (refListCollapsed) — dan is er
// niets te sparen en beantwoordt de lijst de vraag zonder klik.
import { createEffect, createMemo, createSignal, For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  CARD_CHUNK_SIZE, REF_LIST_INLINE_MAX, filterRefItems, incomingRefCount, incomingRefs,
  refListCollapsed,
} from '../../model-grens.js';
import type { Term, Verwijzing } from '../../model-grens.js';
import { graaf, graafVersie } from '../../stores/corpus.js';
import { staatOpen, zetOpen } from '../../stores/openstand.js';
import { vouwstand } from '../gedeeld/vouwstand.js';
import { tekst } from '../../stores/weergave.js';
import { Chevron } from '../gedeeld/chip.jsx';
import { predicaatTekst, refRijTekst } from './verwijzingstekst.js';
import './terugverwijzingen.css';
import { kopBediening } from '../gedeeld/kopselectie.js';

interface RijItem { title: string; sub: string; ref: Verwijzing }

/** Eén verwijzer: naam plus het predicaat waarmee hij verwijst.
 *
 *  EEN IRI WAS HIER TOT 16 SEP 2026 EEN LINK naar diezelfde knoop in de
 *  RDF-verkenner; een blanke knoop kreeg er geen, want die heeft buiten dit
 *  document geen adres en een dode link is erger dan gewone tekst. De verkenner
 *  is gesloopt (eigenaarsbesluit), dus heeft die link geen bestemming meer —
 *  en dan geldt diezelfde redenering voor álle rijen. Elke rij is nu de vorm
 *  die de blanke knoop al had: naam, predicaat, en de IRI als hover. `.usedby-
 *  anon` blijft de klasse van de rij ZONDER adres, want dat verschil is nog
 *  steeds echt — hij is alleen niet meer aan een link te zien. */
function VerwijzerRij(props: { item: RijItem }): JSX.Element {
  const ref = () => props.item.ref;
  return (
    <li class={ref().iri ? 'usedby-ref' : 'usedby-ref usedby-anon'} title={ref().iri || undefined}>
      <span class="usedby-name" title={ref().desc || undefined}>{props.item.title}</span>
      <Show when={props.item.sub}>
        <span class="usedby-pred mono muted" title={ref().predicate?.desc || undefined}>
          {props.item.sub}
        </span>
      </Show>
    </li>
  );
}

export interface TerugverwijzingenProps {
  /** De knoop waar het om gaat. Eén van beide: de IRI, of de term (voor een
   *  blanke knoop, die geen IRI heeft). */
  iri?: string | null;
  term?: Term;
}

/** "Gebruikt door N" — de andere kant van elke verwijzing naar deze knoop.
 *  Verwijst er niets naar, dan komt er geen regel: een "gebruikt door 0" zou
 *  op elk los ding staan en daarmee niets meer zeggen. */
export function Terugverwijzingen(props: TerugverwijzingenProps): JSX.Element {
  // DE STARTSTAND IS DE BASELINE-REGEL `refListCollapsed()` — dezelfde functie
  // waarmee de bevroren viewer zijn verwijzingsblokken opent ("Overeenkomsten
  // op dit aanbod", doc.js) en waarmee de ledenlijst hiernaast werkt. Twee
  // verwijzingen zijn goedkoop en beantwoorden de vraag meteen; boven de
  // drempel is de telling het antwoord en zou de lijst de kaart platwalsen.
  // De telling komt uit de graaf en kan later binnenkomen (endpointmodus), dus
  // de startstand volgt haar tot de lezer zelf klikt — dan wint zijn keuze.
  const [gebouwd, setGebouwd] = createSignal(false);
  const [filter, setFilter] = createSignal('');
  const [limiet, setLimiet] = createSignal(CARD_CHUNK_SIZE);

  const knoop = () => props.term || props.iri || null;
  const aantal = createMemo(() => {
    const g = graaf();
    const k = knoop();
    if (!g || !k) return 0;
    void graafVersie();
    return incomingRefCount(g, k);
  });

  // `usedby:<iri>` is zowel de data-open-key als de sleutel waaronder deze
  // regel zijn stand bewaart (stores/openstand.ts). Alleen als OPENZETTER: de
  // bewaarde set noemt wat open stond, niet wat dicht stond — onder de drempel
  // blijft de regel dus gewoon open staan.
  //
  // FIXRONDE 1 (dt3 lane-toevoegfocus): zie de gelijkluidende noot in
  // `leden.tsx`. De expliciete SLUITING van dit blok leefde in een
  // component-lokaal signaal en ging bij elke hermontage verloren; hij staat nu
  // driestandig in de open-stand-administratie onder dezelfde `usedby:`-sleutel.
  const sleutel = () => (props.iri ? 'usedby:' + props.iri : '');
  const vouw = vouwstand(sleutel);
  const open = () => vouw.handmatig()
    ?? (staatOpen(sleutel()) || !refListCollapsed(aantal()));

  // Een blok dat open GERENDERD wordt (de startstand hierboven, of een
  // herrender met onthouden stand) moet zijn lijst ook echt hebben: het
  // toggle-event van een al open <details> vuurt niet.
  createEffect(() => { if (open()) setGebouwd(true); });

  const items = createMemo<RijItem[]>(() => {
    const g = graaf();
    const k = knoop();
    if (!gebouwd() || !g || !k) return [];
    void graafVersie();
    return incomingRefs(g, k).map((r) => {
      const txt = refRijTekst(r);
      return { title: txt.title, sub: txt.pred || predicaatTekst(r.predicate), ref: r };
    });
  });
  const zichtbaar = createMemo(() => filterRefItems(items(), filter()));
  const getoond = createMemo(() => zichtbaar().slice(0, limiet()));
  const rest = () => zichtbaar().length - getoond().length;

  return (
    <Show when={aantal()}>
      <details
        class="usedby"
        data-open-key={sleutel() || undefined}
        open={open()}
        onToggle={(e) => {
          const aan = (e.currentTarget as HTMLDetailsElement).open;
          vouw.onthoud(aan);
          zetOpen(sleutel(), aan);
        }}
      >
        <summary class="usedby-sum muted" title={tekst('usedBy.title')} {...kopBediening()}>
          <span class="usedby-count">{tekst('usedBy.count', { n: aantal() })}</span>
          <Chevron klein />
        </summary>
        <Show when={gebouwd()}>
          <Show when={items().length > REF_LIST_INLINE_MAX}>
            <input
              type="search"
              class="usedby-filter"
              placeholder={tekst('usedBy.filterPlaceholder')}
              aria-label={tekst('usedBy.filterAria')}
              value={filter()}
              onInput={(e) => { setFilter(e.currentTarget.value); setLimiet(CARD_CHUNK_SIZE); }}
            />
          </Show>
          <ul class="usedby-list">
            <For each={getoond()}>{(item) => <VerwijzerRij item={item} />}</For>
          </ul>
          <button
            type="button"
            class="btn usedby-more"
            hidden={rest() <= 0}
            onClick={() => setLimiet((n) => n + CARD_CHUNK_SIZE)}
          >{tekst('list.showMoreRest', { n: rest() })}</button>
        </Show>
      </details>
    </Show>
  );
}
