// DE INTENSIONELE COLLECTIE — bevinding I-4.
//
// Een odrl:PartyCollection of odrl:AssetCollection is meer dan een naam. Zij
// kan haar leden OPSOMMEN (extensioneel; dat is de ledenlijst van leden.tsx),
// maar zij kan ze ook BESCHRIJVEN: "elke partij waarvoor geldt dat afdeling
// gelijk is aan Burgerzaken" (intensioneel, odrl:refinement + odrl:source).
// De bevroren viewer toont die beschrijving als een uitklap met drie dingen —
// de SOORT ("Groep"), de BRON ("Groep medewerkers van Gemeente Vlierdam") en de
// sectie "Afbakening" met de refinement-rijen — en dat blok was in de nieuwe
// app nooit gebouwd.
//
// Gemeten vóór deze herbouw, op vlierdam en het voorbeeldcorpus: `party-coll`
// 1 → 0, `coll-fold` 1 → 0, `coll-refinement` 1 → 0, `coll-summary`/
// `coll-source-line`/`coll-refinements` alle 1 → 0. De nieuwe app toonde alleen
// `Afnemer = medewerkers Burgerzaken vlierdam:medewerkers-burgerzaken`; wáárom
// die groep die groep is, stond nergens.
//
// Gedragsbron: `collectionNodes`, `collectionBody`, `collectionSourceValue`,
// `collKindChip` en `collectionRefinementSection` (viewer-bevroren/assets/doc.js
// r.6191-6307). Drie vormen, precies als daar:
//
//   1. GEEN INTENSIE — alleen de naam-tag, met (bij opgesomde leden) de
//      bestaande ledenuitklap eronder. Dat is wat de nieuwe app al deed.
//   2. ANONIEM MET INTENSIE — er is geen naam om een uitklap achter weg te
//      klappen, dus staat de body er direct, met de soortchip ervoor.
//   3. BENOEMD MET INTENSIE — de naam is wat de lezer hier zoekt, de afbakening
//      eronder is navraag: dus ingeklapt, met dezelfde chevron-conventie als de
//      ledenlijst en een `data-open-key` zodat de open-stand een herrender
//      overleeft.
//
// De REFINEMENT-RIJEN krijgen bewust de slot-chips van de Voorwaarden-rijen van
// een regel: een refinement ÍS een voorwaarde, en dezelfde soort informatie
// hoort er overal hetzelfde uit te zien. Ze staan onder een eigen sectiebalk
// ("Afbakening") — een refinement bakent de verzameling af, hij stelt geen
// voorwaarde aan het gebruik.
import { For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { staatOpen, zetOpen } from '../../stores/openstand.js';
import { bewerklaagActief, Haak } from '../gedeeld/bewerkhaak.jsx';
import { tekst } from '../../stores/weergave.js';
import { Chevron } from '../gedeeld/chip.jsx';
import { Kv, TermKop } from '../gedeeld/kop.jsx';
import { kopBediening } from '../gedeeld/kopselectie.js';
import { Leden } from './leden.jsx';
import type { CollectieDesc } from './leden.jsx';
import { ChipRuimte, ConstraintChips } from './voorwaarde-inhoud.jsx';
import type { Voorwaarde } from './voorwaarde-inhoud.jsx';
import { VoorwaardeInvullingKnop } from './voorwaarden.jsx';
import './collectie.css';

/** De intensionele definitie zoals `collectionIntension` haar oplevert. */
export interface Intensie {
  kind?: string | null;
  refinements?: Voorwaarde[];
  phrase?: string | null;
  /** odrl:source — de verzameling WAARUIT deze collectie snijdt. Mag een
   *  literal zijn (DOME zet er runtime-sleutels als "urn:user" in); dan geen
   *  curie en geen ⌕. */
  source?: { iri?: string | null; curie?: string | null; label?: string | null } | null;
}

/** Wat een target of partij aan collectie-eigenschappen draagt. */
export interface CollectieKnoop extends CollectieDesc {
  intension?: Intensie | null;
}

/** Draagt deze knoop iets waarvoor het collectieblok nodig is? */
export function isCollectie(d: CollectieKnoop | null | undefined): boolean {
  return !!d && (!!d.intension || !!(d.members || []).length || !!d.collKind);
}

/** WANNEER HANGT DE LEDENLIJST ERONDER — en waarom dat op de twee plekken
 *  waar zij kan staan NIET hetzelfde antwoord is.
 *
 *  `doc.js` hangt `targetMembersFold` op beide plekken aan `members.length`
 *  (r.6262 in `collectionBody`, r.6284 in `collectionNodes`): geen opgesomde
 *  leden in het model, geen uitklap. De leden-lane koos voor de plek ZONDER
 *  intensie bewust anders — `<Show when={tg.collKind}>`, met de noot "de Show
 *  gaat over het collectie-ZIJN, niet over de lengte (leden-report,
 *  integratiepunt 2: kies er één)" — en die keuze is per ongeluk teruggedraaid
 *  toen deze component de regel uit `regels.tsx` overnam (MIN-1 van het
 *  gecombineerde review-seat). Zij staat nu terug, met een reden die verder gaat
 *  dan "een andere lane besloot het": `<Leden>` leest de GRAAF
 *  (`memberTreeLevel`) en haalt in endpoint-modus zelf een niveau op, dus
 *  `desc.members` leeg betekent niet "er zijn geen leden". Poorten op de lengte
 *  verbergt zo'n collectie helemaal, en dan is een verzameling niet van een
 *  gewoon asset te onderscheiden.
 *
 *  MAAR NIET IN DE INTENSIONELE BODY. Daar is de verzameling al beschreven — de
 *  sectie "Afbakening" staat er twee regels boven — en een enumeratie is dan
 *  niet het verhaal. Gemeten wat er gebeurt als je hem daar óók verruimt: op
 *  vlierdam en het voorbeeldcorpus zegt "medewerkers Burgerzaken" dan
 *  `0 partijen — geen leden gevonden` ONDER zijn eigen afbakening. Dat leest als
 *  "deze groep is leeg" terwijl de groep juist gedefinieerd is; het is een
 *  slechtere mededeling dan zwijgen. Daar blijft dus de vorm van de bevroren
 *  viewer staan (`CollectieBody` hieronder poort op de lengte).
 *
 *  Draagt een knoop wél leden in het model maar geen `collKind` (een
 *  ongetypeerde `dct:hasPart`-keten op een target), dan telt de lengte alsnog —
 *  dat is het geval dat de bevroren viewer óók toont. */
function toontLeden(d: CollectieKnoop): boolean {
  return !!d.collKind || !!(d.members || []).length;
}

/** De soortchip vóór een collectie-waarde: "Groep" (partijen) of "Verzameling"
 *  (assets). Klein en woordelijk — hij zegt de lezer WAT voor ding hier staat,
 *  zodat een naam als "medewerkers Burgerzaken" niet voor één partij wordt
 *  aangezien. */
export function SoortChip(props: { kind?: string | null }): JSX.Element {
  return (
    <span class="kind-pill coll">
      {tekst(props.kind === 'party' ? 'coll.kindParty' : 'coll.kindAsset')}
    </span>
  );
}

/** De waarde van het veld "Bron": ‹soortchip› + naam + ⌕. Zonder odrl:source is
 *  er niets te tonen — de collectie zelf ÍS dan de verzameling, en die staat al
 *  in de kop; dan blijft het veld weg in plaats van de eigen naam te herhalen.
 *
 *  BLIJFT LEESKANT, met opzet. De bevroren viewer bood op `odrl:source` geen
 *  bewerkroute (`collectionSourceValue`, doc.js r.6238-6250), en de brief zegt
 *  pariteit eerst: wat doc.js daar niet had is een gelabelde verbetering en dus
 *  een eigen besluit, geen bijvangst van deze ronde. De bron van een collectie is
 *  bovendien geen naam maar een STRUCTUURkeuze (waaruit snijdt deze verzameling),
 *  en een combobox die dat stilzwijgend omzet is een grotere stap dan hij lijkt. */
function BronWaarde(props: { src: NonNullable<Intensie['source']>; kind?: string | null }): JSX.Element {
  return (
    <span class="coll-source-line">
      <SoortChip kind={props.kind} />
      <ChipRuimte />
      <span class="coll-source-name">{props.src.label || props.src.curie || ''}</span>
    </span>
  );
}

/** De sectie "Afbakening": de refinement-rijen, elk met de chips, het ⌕ en het
 *  raderwiel van een gewone voorwaarde-rij. Een intensie ZONDER uitgepakte
 *  refinements houdt haar lopende zin — dat vangnet staat ook in de bevroren
 *  viewer.
 *
 *  EN SINDS DEZE RONDE MET DE ACTIESTROOK VAN EEN VOORWAARDE-RIJ
 *  (eigenaarsvraag 8 sep 2026: "Waarom is dit niet editable?"). Een refinement
 *  ÍS een voorwaarde — dat is precies de reden dat deze rijen de slot-chips van
 *  een voorwaarde dragen — dus krijgt hij ook haar bewerkroute: het ✎ opent de
 *  sloteditor, het ✕ maakt hem los. Er komt geen tweede mechanisme naast; het is
 *  dezelfde haak die de Voorwaarden-sectie van een regel gebruikt.
 *
 *  GEEN `regel` in de ctx: een collectie-refinement hangt aan de COLLECTIE en
 *  niet aan een regel. `voorwaardeAnker` valt dan terug op zijn "maar één
 *  kandidaat"-tak en vindt de collectie — precies goed, want dat is de enige
 *  koppeling die er is.
 *
 *  GELABELDE VERBETERING: de bevroren viewer bood hier niets (`collectionBody`
 *  en `collectionRefinementSection`, doc.js r.6191-6264, dragen geen enkele
 *  bewerk-affordance). Zij is klein — één haak, geen nieuw mutatiepad — en zij
 *  beantwoordt een expliciete vraag van de eigenaar. */
function Afbakening(props: { ix: Intensie | null; term: unknown }): JSX.Element {
  const refs = () => (props.ix && props.ix.refinements) || [];
  return (
    <>
      {/* DE LOPENDE ZIN blijft het vangnet van een intensie waarvan de
          refinements niet zijn uitgepakt — precies zoals in de bevroren viewer.
          Hij staat nu naast de sectie in plaats van als `fallback` erbinnen:
          sinds de sectie zich ook in de BEWERKSTAND opent (zie hieronder), zou
          een `fallback` de zin daar laten verdwijnen. */}
      <Show when={!refs().length && props.ix && props.ix.phrase}>
        <span class="coll-phrase">{props.ix!.phrase}</span>
      </Show>
      {/* DE SECTIE STAAT ER IN DE BEWERKSTAND OOK ZONDER REFINEMENT
          (eigenaarsbevinding 9 sep 2026: "een PartyCollection met refinements
          [is] ook niet aan te maken"). Een verse groep heeft er per definitie
          nul, en zonder deze uitzondering is er geen plek waar de eerste kan
          ontstaan — letterlijk dezelfde afweging als bij de lege
          Voorwaarden-sectie van een regel (`Voorwaarden` in voorwaarden.tsx) en
          bij `constraintsSection` in de bevroren viewer. In de KIJKSTAND
          verandert er niets: geen refinement, geen kop. */}
      <Show when={refs().length || bewerklaagActief()}>
      <TermKop tag="h4" sleutel="coll.refinementSection" />
      <ul class="clean coll-refinements">
        <For each={refs()}>{(r) => (
          <li class="coll-refinement" title={[r.label, r.comment].filter(Boolean).join(' — ') || undefined}>
            <ConstraintChips c={r} />
            {/* Dezelfde kopieerbare spaties als op een voorwaarderij. Deze rij
                is GEEN flexrij (zie collectie.css), dus hier vervangt de ruimte
                geen gap maar vult zij een echte leegte: vóór deze ronde plakten
                de noot en de twee knoppen tegen de chips aan, ook visueel. */}
            <Show when={r.label}>{(l) => (
              <><ChipRuimte /><span class="c-note muted">{l()}</span></>
            )}</Show>
            <ChipRuimte />
            <ChipRuimte />
            <VoorwaardeInvullingKnop c={r} />
            <Haak naam="voorwaardeStrook" ctx={{ c: r, regel: null }} />
          </li>
        )}</For>
        {/* DE GHOST SLUIT DE LIJST AF, op de plek waar de nieuwe rij komt —
            dezelfde vorm en dezelfde plaatsingsregel als de voorwaarde-ghost van
            een regel. Wat hij aanmaakt is een `odrl:refinement` op de COLLECTIE
            (niet op een actie-knoop: een groep heeft er geen), en de sloteditor
            opent er meteen op via het focusverzoek. */}
        <Haak naam="collectieGhost" ctx={{ term: props.term }} />
      </ul>
      </Show>
    </>
  );
}

/** De body van een intensionele collectie: dezelfde opbouw als de body van een
 *  regelrij — eerst het WAT als veld (de bron), dan de sectiebalk met de
 *  afbakening, en tot slot een eventuele ledenlijst. */
function CollectieBody(props: {
  desc: CollectieKnoop; ix: Intensie | null; extra?: string;
}): JSX.Element {
  const kind = () => props.desc.collKind || (props.ix && props.ix.kind) || 'asset';
  const term = () => props.desc.term ?? props.desc.iri ?? null;
  // WELKE LEDENPOORT, en waarom die van de omstandigheden afhangt. Draagt deze
  // collectie een AFBAKENING, dan geldt de regel uit de bevroren viewer: poort
  // op de lengte, want "0 partijen — geen leden gevonden" onder een eigen
  // afbakening leest als "deze groep is leeg" terwijl zij juist beschreven is.
  // Draagt zij er GEEN — de body staat er dan alleen in de bewerkstand, om de
  // eerste te kunnen maken — dan geldt `toontLeden`: precies wat de fallback
  // hieronder in de kijkstand ook doet, zodat een getypeerde lege groep in beide
  // standen hetzelfde over zijn leden zegt.
  const toonLeden = () => (props.ix
    ? (props.desc.members || []).length > 0 : toontLeden(props.desc));
  return (
    <div class={'coll-body' + (props.extra ? ' ' + props.extra : '')}>
      <Show when={props.ix && props.ix.source}>{(src) => (
        <Kv rijen={[{
          sleutel: 'field.source',
          waarde: <BronWaarde src={src()} kind={kind()} />,
          ref: src().iri,
        }]}
        />
      )}</Show>
      <Afbakening ix={props.ix} term={term()} />
      <Show when={toonLeden()}><Leden desc={props.desc} /></Show>
    </div>
  );
}

/** Een knoop die (ook) een collectie kan zijn: de naam-tag die de aanroeper
 *  levert, plus de lagen die de data draagt. Draagt zij beide vormen — opgesomde
 *  leden én een intensie — dan verschijnen ze onder elkaar; er valt er nooit
 *  stilzwijgend één weg. */
export function Collectie(props: {
  desc: CollectieKnoop;
  /** De naam-tag. Krijgt de IRI mee, of `null` bij een anonieme collectie —
   *  dan draagt de tag zelf geen adres. */
  tag: (iri: string | null) => JSX.Element;
}): JSX.Element {
  const ix = () => props.desc.intension || null;
  const kind = () => props.desc.collKind || (ix() && ix()!.kind) || 'asset';
  const sleutel = () => (props.desc.iri ? 'colldef:' + props.desc.iri : undefined);
  const open = () => (sleutel() ? staatOpen(sleutel()!) : false);
  // WANNEER STAAT DE BODY ER: bij een intensie altijd (dat is de leesvorm van
  // bevinding I-4), en in de BEWERKSTAND ook bij een PARTIJ-collectie zónder
  // intensie. Dat tweede is de aanmaakroute van 9 sep 2026: een verse
  // `odrl:PartyCollection` heeft nog geen enkele refinement, en zonder body is
  // er geen "Afbakening"-sectie en dus geen plek waar de eerste kan ontstaan.
  // In de kijkstand verandert er niets — daar blijft een collectie zonder
  // intensie precies wat zij was: haar naam-tag met (bij leden) de uitklap.
  //
  // ALLEEN `party`, EN DAT IS EEN AFBAKENING VAN DEZE RONDE (ruling). Dezelfde
  // component tekent ook de DOELOBJECT-collecties, en die zijn er veel: elke
  // `odrl:AssetCollection` in een regel zou in de bewerkstand een lege
  // "Afbakening"-sectie krijgen. Dat is een uitbreiding die niemand vroeg, zij
  // verandert het beeld van elke gegevensset-tag, en zij is gemeten schadelijk —
  // `e2e/gevallen/sloteditor.mjs` klikte daarna de ghost van de gegevensset in
  // plaats van die van de regel (`.voorwaarde-plus-knop` binnen dezelfde rij).
  // De bevinding gaat over de AFNEMER; een asset-collectie die haar afbakening
  // ook zo wil krijgen is een eigen besluit. Kost bij ongelijk: één woord hier.
  const toonBody = () => ix() || (bewerklaagActief() && props.desc.collKind === 'party');
  return (
    <Show
      when={toonBody()}
      fallback={(
        <>
          {props.tag(props.desc.anon ? null : props.desc.iri || null)}
          <Show when={toontLeden(props.desc)}><Leden desc={props.desc} /></Show>
        </>
      )}
    >
      <Show
        when={!props.desc.anon}
        fallback={(
          <>
            <SoortChip kind={kind()} />
            <ChipRuimte />
            <CollectieBody desc={props.desc} ix={ix()} />
          </>
        )}
      >
        <details
          class="coll-fold"
          data-open-key={sleutel()}
          // EEN GROEP ZONDER AFBAKENING STAAT IN DE BEWERKSTAND OPEN. De vouw
          // bestaat omdat de NAAM is wat de lezer zoekt en de afbakening
          // navraag; heeft de groep er nog geen, dan is die navraag het enige
          // wat erin zit — en dan verbergt de vouw precies de plek waar de
          // eerste afbakening moet ontstaan (gemeten op een verse groep: de
          // "Afbakening"-sectie en haar toevoegplek zaten achter een dichte
          // chevron). Zodra er een afbakening staat, wint de bewaarde stand
          // weer: dan is er iets om weg te klappen.
          open={open() || (bewerklaagActief() && !ix())}
          onToggle={(e) => { if (sleutel()) zetOpen(sleutel()!, e.currentTarget.open); }}
        >
          <summary class="vl-summary coll-summary" {...kopBediening()}>
            <SoortChip kind={kind()} />
            {/* DE SPATIE NA DE SOORTCHIP (eigenaarsbesluit 8 sep 2026,
                "kopieerbare tekst"). De chip en de naam stonden rug-aan-rug met
                alleen een CSS-`gap` ertussen, en een gap komt niet mee in het
                klembord: de kop plakte als "Groepmedewerkers Burgerzaken".
                Zelfde besluit en dezelfde bouwsteen als bij de slot-chips van
                een voorwaarde — dat het hier een `.kind-pill` is in plaats van
                een `.c-slot` maakt voor de lezer die de rij plakt niets uit.
                Zie `ChipRuimte` in voorwaarde-inhoud.tsx. */}
            <ChipRuimte />
            {props.tag(props.desc.iri || null)}
            <Chevron />
          </summary>
          <CollectieBody desc={props.desc} ix={ix()} extra="coll-fold-body" />
        </details>
      </Show>
    </Show>
  );
}
