// Het TEKSTFILTER van de zijnav: één zoekveld met een teller ernaast.
//
// Gedragsbron: de filterrij uit ensureTreeChrome + updateTreeCount in de
// bevroren viewer. Eigen aan de boom — het raakt de document-filters
// (kaartenlijst, sectiekoppen) niet aan.
//
// De teller blijft LEEG zolang er niet gefilterd wordt: een teller die altijd
// een getal toont is ruis zolang er niets aan de hand is. Hij is aria-live,
// zodat een schermlezer hoort wat het typen oplevert.
//
// Het filter is bewust GEEN bewaarde voorkeur: een verborgen (gefilterde) boom
// die de lezer na het herladen niet meer als gefilterd herkent, is verwarrender
// dan opnieuw moeten typen.
import { tekst } from '../../stores/weergave.js';

export interface FilterProps {
  /** De ruwe filtertekst; de eigenaar (zijnav) houdt hem vast. */
  query: string;
  zetQuery: (q: string) => void;
  /** Aantal rijen dat het filter overhoudt, en het totaal. */
  getoond: number;
  totaal: number;
  /** Het veld doorgeven aan de eigenaar: de Escape-laag moet weten of de focus
   *  hier staat. */
  ref?: (el: HTMLInputElement) => void;
}

export function Filter(props: FilterProps) {
  const telling = () => (props.query.trim()
    ? tekst('count.ofTotal', { n: props.getoond, total: props.totaal })
    : '');
  return (
    <div class="tree-filter-row">
      <input
        type="search"
        class="tree-filter"
        value={props.query}
        placeholder={tekst('tree.filterPlaceholder')}
        aria-label={tekst('tree.filterAria')}
        ref={(el) => props.ref?.(el)}
        onInput={(e) => props.zetQuery(e.currentTarget.value || '')}
      />
      <span class="tree-count" aria-live="polite">{telling()}</span>
    </div>
  );
}
