// DE KAARTENLIJST — één lijstsectie vol kaarten, lui en gechunkt.
//
// Gedragsbron: `setsCardsView` en `agreementsListView` in de bevroren viewer
// (viewer-bevroren/assets/doc.js). Die twee verschilden alleen in wat er in de kop van
// een kaart stond en welke filters de sectie had; de mechaniek — dicht starten,
// body lazy, per CARD_CHUNK_SIZE bijtekenen, filteren herstart de chunks —
// was identiek. Hier is het dus één component, met de verschillen als props.
//
// DRIE LAZY-DIMENSIES houden de DOM klein op BRP-schaal (1.392 overeenkomsten):
//   1. kaarten starten INGEKLAPT en hun BODY wordt pas gebouwd bij de eerste
//      uitklap (`lazy` op <Kaart>; de summary-kop is licht);
//   2. de LIJST groeit per chunk, bijgeladen door een IntersectionObserver-
//      sentinel onderaan met een "Meer laden"-knop als terugval;
//   3. in endpointmodus haalt een kaart bij zijn eerste uitklap zijn DETAIL op
//      (`haalDetail`), precies zoals ensureDetail dat deed.
//
// WAT DE LEZER ZELF OPENZETTE komt bij een volgend bezoek terug: de open-stand
// staat per BRONNENCORPUS in localStorage (prefs.js), met dezelfde sleutelvorm
// als de bevroren viewer — 'open:' + de gesorteerde bronnen. Zoals daar is de
// bewaarde stand een ADMINISTRATIE en geen momentopname van de DOM: elke
// toggle werkt alleen ZIJN EIGEN sleutel bij, want wat er niet staat (de
// volgende chunk, een weggefilterde kaart) mag niet stilzwijgend vergeten
// worden.
import {
  createEffect, createMemo, createResource, createRoot, createSignal, For, on, onCleanup,
  Show,
} from 'solid-js';
import type { JSX } from 'solid-js';
import {
  cardChunk, CARD_CHUNK_SIZE, filterIndexRows,
  partyLabel, policyAssignee, policyLifecycle, refListCollapsed, setIndexRows,
} from '../../model/parse.js';
import { detailNodig, haalDetail, lijstFase, model } from '../../stores/corpus.js';
import { corpusSleutel, staatOpen, zetOpen } from '../../stores/openstand.js';
import { registreerOnthuller, tekst, weergave } from '../../stores/weergave.js';
import { invullingIndex } from '../kaart/invulling.jsx';
import { Kaart } from '../kaart/kaart.jsx';
import type { Kaartsoort, Policy } from '../kaart/kaart.jsx';
import type { Sectiefilter } from './sectiefilter.jsx';
import { Versienav, versieTitel } from './versienav.jsx';
import './lijst.css';

/** Eén rij van de lijst: het LICHTE beeld van een kaart. Genoeg voor de
 *  kopregel, het filter en de teller; de volledige policy wordt pas opgezocht
 *  wanneer de kaart gebouwd wordt. */
export interface LijstItem {
  iri: string;
  titel: string;
  /** Afnemer of indiener — waar het tekstfilter naast de titel op zoekt. */
  sub: string | null;
  /** Levensfase voor het statusfilter (null = actief). */
  status: string | null;
  /** De aanbod-IRI's waar deze kaart aan hangt (aanbodfilter). */
  aanbodIris: string[];
  /** Wat er ná de regeltelling in de kop staat: "3 versies", "vanaf …",
   *  "vervangen". */
  extraBits: string[];
  /** De regeltelling uit de indexrij — de terugval zolang de policy zelf nog
   *  niet geladen is (endpoint-skelet). */
  regels: number;
  /** Overschrijft de afgeleide kaartsoort. */
  soort?: Kaartsoort;
  /** De kaart ZELF, voor rijen die geen policy in het model hebben: een
   *  beëindigd besluit bestaat er alleen nog als documentversie en wordt door
   *  `stubPolicy` samengesteld. Staat hij er niet, dan zoekt de kaart haar
   *  policy gewoon in het model op. */
  policy?: Policy;
}

// --- De rijen ---------------------------------------------------------------

/** Beleidssets en verzoeken: het lichte indexbeeld uit de modellaag, met de
 *  levensfase erbij. Een niet-geldende versie binnen een container krijgt geen
 *  eigen rij (setIndexRows laat hem weg); de kaart van de container toont de
 *  geldende versie. */
export function rijenVanSets(sets: Policy[], containers: unknown): LijstItem[] {
  const m = model();
  const rijen = setIndexRows(sets, containers) as Array<Record<string, any>>;
  return rijen.map((r) => {
    const bits: string[] = [];
    if (r.versions != null && r.versions > 1) bits.push(tekst('versions.count', { n: r.versions }));
    if (r.effectiveFrom) bits.push(tekst('summary.from', { date: r.effectiveFrom }));
    if (r.superseded) bits.push(tekst('summary.superseded'));
    return {
      iri: r.iri,
      titel: r.title,
      sub: r.assignee || null,
      status: policyLifecycle(m, sets[r.idx]) as string,
      aanbodIris: sets[r.idx]?.offers || [],
      extraBits: bits,
      regels: r.rules || 0,
    };
  });
}

/** Overeenkomsten. Zij hebben geen indexrij-vorm in de modellaag (hun lijst
 *  komt uit de nav), dus het lichte beeld wordt hier samengesteld — met
 *  dezelfde velden als hierboven, zodat de lijst maar één rijvorm kent. */
export function rijenVanOvereenkomsten(agrs: Policy[]): LijstItem[] {
  const m = model();
  return agrs.map((a) => ({
    iri: a.iri,
    titel: a.title || a.iri,
    sub: partyLabel(policyAssignee(a)) || null,
    status: policyLifecycle(m, a) as string,
    aanbodIris: a.offers || [],
    extraBits: [],
    regels: (a.permissions || []).length + (a.prohibitions || []).length
      + (a.obligations || []).length,
    soort: 'agreement' as Kaartsoort,
    // Alleen een STUB draagt zijn eigen kaart mee: hij staat niet in het model
    // en zou anders als lege placeholder renderen.
    policy: a.stub ? a : undefined,
  }));
}

// --- Open-stand per bronnencorpus -------------------------------------------
// De administratie zelf staat in `stores/openstand.ts`: de kaarten delen hem
// met de ledenboom (`coll:`/`tree:`) en de terugverwijzingen (`usedby:`),
// precies als de ene `openState`-set van de bevroren viewer. Hier staat alleen
// wat EIGEN is aan een kaart.

export { corpusSleutel };

// WAT DE LEZER TIJDENS FASE 1 ZELF OPENKLAPTE — op MODULE-niveau, en dat is de
// hele pointe. De rem hieronder gaat over de ONTHOUDEN stand; wat de lezer NU
// zelf opent hoort open te blijven. Een component-lokaal signaal kan dat niet
// dragen: zodra het detail landt wordt het model herbouwd, levert de rijen-memo
// nieuwe item-objecten en bouwt `<For>` de `Lijstkaart` opnieuw — het signaal is
// dan weg en Solid schrijft `open={false}` naar een <details> die de lezer net
// had geopend. Gemeten door het review-seat (bevinding N-1): +0 ms open,
// +50 ms dicht, precies het venster van de CONSTRUCT-retour.
//
// Deze set overleeft die herbouw. Hij is per BRONNENCORPUS, net als de
// onthouden stand zelf: een IRI uit een vorig corpus zegt hier niets.
const zelfGeopend = new Set<string>();
let zelfSleutel: string | null = null;
const [zelfVersie, zetZelfVersie] = createSignal(0);

function zelfGeopendVoorCorpus(): Set<string> {
  const sleutel = corpusSleutel();
  if (zelfSleutel !== sleutel) {
    zelfGeopend.clear();
    zelfSleutel = sleutel;
  }
  return zelfGeopend;
}

// De set geldt per EERSTE-BEELD-FASE, niet per sessie: begint er een nieuwe
// lading, dan is wat de lezer vóór de herlading openzette weer gewoon
// ONTHOUDEN stand — en daarvoor geldt de rem van T3 wel. Een module-effect is
// hier het juiste gereedschap: de fase is een signaal, dus de overgang ERIN is
// waarneembaar; hem bij elke uitlezing bemonsteren zou de overgang missen zodra
// er tussendoor niets rendert.
createRoot(() => {
  createEffect(on(lijstFase, (nu) => {
    if (nu !== 'eerste') return;
    zelfGeopend.clear();
    zetZelfVersie((v) => v + 1);
  }));
});

/** Wat de lezer bij zijn vorige bezoek open had staan. In de EERSTE-BEELD-fase
 *  van de tweefasige endpoint-lading blijft alles dicht: een open kaart bouwt
 *  meteen zijn body en haalt daarvoor een detail-CONSTRUCT op — precies wat die
 *  fase wil uitstellen. (Die rem geldt alleen voor KAARTEN: een blok binnen een
 *  kaart bestaat in die fase toch niet, en zou door dezelfde rem juist
 *  dichtklappen op het moment dat de lezer het opende.)
 *
 *  De rem geldt NIET voor wat de lezer in díe fase zelf openklapte: die kaart
 *  heeft zijn detail al opgehaald en hoort open te blijven staan. */
export function onthoudenOpen(iri: string): boolean {
  if (lijstFase() === 'eerste') {
    zelfVersie();                             // reactief op elke eigen klik
    return zelfGeopendVoorCorpus().has(iri);
  }
  return staatOpen(iri);
}

/** Eén kaart wisselde van stand: alleen díe sleutel bijwerken en wegschrijven.
 *  In de eerste-beeld-fase gaat de stand ook de sessie-set in, zodat hij de
 *  modelherbouw overleeft die het bijgeladen detail meebrengt. */
export function onthoudOpen(iri: string, open: boolean): void {
  if (lijstFase() === 'eerste') {
    const s = zelfGeopendVoorCorpus();
    if (open) s.add(iri); else s.delete(iri);
    zetZelfVersie((v) => v + 1);
  }
  zetOpen(iri, open);
}

// --- Eén kaart in de lijst --------------------------------------------------

/** De policy achter een rij, uit het HUIDIGE model. Reactief: haalt een
 *  detail-CONSTRUCT het model opnieuw op, dan volgt de kaart vanzelf. */
function policyVan(iri: string): Policy | null {
  const m = model() as unknown as { sets?: Policy[]; offers?: Policy[]; agreements?: Policy[] } | null;
  if (!m) return null;
  for (const lijst of [m.sets, m.offers, m.agreements]) {
    const p = (lijst || []).find((x) => x.iri === iri);
    if (p) return p;
  }
  return null;
}

interface LijstkaartProps {
  item: LijstItem;
  compact?: boolean;
  /** Deze kaart moet open, ongeacht wat er onthouden is (deeplink of sprong,
   *  of een klein corpus waarin de sectie alles meteen toont). */
  dwingOpen?: boolean;
}

function Lijstkaart(props: LijstkaartProps): JSX.Element {
  // DE VERSIENAVIGATOR wisselt de kaart naar een andere versie van hetzelfde
  // besluit. Dat is puur weergave van DEZE kaartplek: de rij blijft dezelfde
  // (de lijstindex hangt aan de container), alleen de policy die hij toont
  // verandert. De bevroren viewer herbouwde daarvoor de kaart-DOM; hier is het
  // één signaal.
  const [versieIri, zetVersieIri] = createSignal<string | null>(null);
  const iri = () => versieIri() || props.item.iri;
  const pol = () => policyVan(iri())
    ?? (iri() === props.item.iri ? props.item.policy ?? null : null);
  const [fout, zetFout] = createSignal('');
  // WAT DE LEZER NU ZELF OPENKLAPT staat in `onthoudenOpen`, niet in een
  // component-lokaal signaal: die laatste overleeft de modelherbouw niet die het
  // bijgeladen detail meebrengt (bevinding N-1). Wat de lezer TERWIJL de
  // eerste-beeld-fase loopt zelf openklapt hoort zich te vullen — de bevroren
  // viewer doet daar meteen een `ensureDetail`; zonder dat haalde zo'n kaart
  // niets op (bevinding C3: 0 CONSTRUCTs tegen 1 oud).
  const gescopet = () => weergave.policyScope === iri() || weergave.setScope === iri();
  const open = () => props.dwingOpen || gescopet() || onthoudenOpen(props.item.iri);

  // De kop-extra's: wat de kaart zelf niet weet. De REGELTELLING staat alleen
  // hier zolang de policy nog niet geladen is (endpoint-skelet) — anders telt
  // <Kaart> zelf, en zou hij dubbel staan.
  const bits = () => {
    const p = pol();
    const uit = [...props.item.extraBits];
    if (!p && props.item.regels && !props.compact) {
      uit.unshift(tekst('rules.count', { n: props.item.regels }));
    }
    return uit;
  };

  // DE HYDRATIE, als resource-toestand in plaats van als losse promise.
  // Endpointmodus: zodra de kaart opengaat en haar detail nog ontbreekt, haalt
  // deze resource het CONSTRUCT op; zolang dat loopt toont <Kaart> binnen zijn
  // <Suspense>-grens de skeletregels in plaats van een lege body. Landt het
  // detail, dan wordt het model herbouwd, is `detailNodig` onwaar en valt de
  // bron terug op `undefined` — de resource is dan weer onbewerkt en de body
  // staat er. Faalt het, dan meldt de kaart de reden en blijft zij staan: beter
  // iets dan niets, precies zoals bij de fase-2-fout.
  const [detail] = createResource(
    () => (open() && detailNodig(pol() ?? { iri: iri() }) ? iri() : undefined),
    async (doel: string) => {
      zetFout('');
      try {
        await haalDetail(doel);
      } catch (e: unknown) {
        zetFout(tekst('err.detailLoad', { msg: e instanceof Error ? e.message : String(e) }));
      }
      // NIETS renderbaars: deze resource is er om gelezen te worden.
      return null;
    },
  );

  return (
    <>
      <Kaart
        pol={(pol() || {
          // Plaatshouder: de titel komt van de VERSIE waar de chip naar wijst,
          // niet van de lijstrij — die draagt de titel van de versie die er
          // stónd (bevinding I3, gelijkgetrokken met `Aanbodkaart`).
          iri: iri(), title: versieTitel(iri()) ?? props.item.titel, kind: props.item.soort,
        }) as Policy}
        soort={props.item.soort}
        open={open()}
        lazy
        compact={props.compact}
        detail={weergave.policyScope === iri()}
        hydrateer={() => detail()}
        kopExtra={(
          <>
            <Show when={bits().length}>
              <span class="op-sum muted">{bits().join(' · ')}</span>
            </Show>
            <Versienav iri={iri()} onWissel={(naar) => zetVersieIri(naar)} />
          </>
        )}
        onKlap={(aan: boolean) => onthoudOpen(props.item.iri, aan)}
      />
      <Show when={fout()}><p class="src-err">{fout()}</p></Show>
    </>
  );
}

// --- De lijst ---------------------------------------------------------------

/** De KAART waar deze ref bij hoort, als die in deze lijst staat. `null` = niet
 *  van ons (dan probeert de volgende onthuller het).
 *
 *  De invulling-index (taak 8) legt per `data-ref` vast welke regel of
 *  voorwaarde erachter zit en uit welke policies zij komt; dat is precies de
 *  `policyOfRule`-stap van de bevroren viewer, alleen dan al gebouwd en
 *  gecachet per model. Een regel die in meer beleidssets staat levert meer
 *  scopes: de eerste die in DEZE lijst voorkomt wint — dezelfde volgorde als
 *  `resolveCardFor`, dat de secties in beeldvolgorde afloopt. */
function eigenaarInLijst(ref: string, items: LijstItem[]): string | null {
  const ingang = invullingIndex().get(ref);
  for (const sc of (ingang && ingang.scopes) || []) {
    if (sc.iri && items.some((r) => r.iri === sc.iri)) return sc.iri;
  }
  return null;
}

export interface KaartenlijstProps {
  items: LijstItem[];
  filter: Sectiefilter;
  /** De compacte verzoek-vorm (kenmerk/datum/indiener als subtitel). */
  compact?: boolean;
  /** Roep dit aan vóór een sprong: de sectie moet open staan. */
  onOnthul?: () => void;
  /** Start de kaarten OPEN zolang het er weinig zijn (≤ REF_LIST_INLINE_MAX).
   *  Zo doet de bevroren viewer het bij de Overeenkomsten-sectie: een klein
   *  corpus is één doorlopend leesstuk, op schaal ingeklapt met lazy body's.
   *  In de eerste-beeld-fase blijft alles dicht — een open kaart haalt zijn
   *  detail op, en dat is precies wat die fase wil uitstellen. */
  openBijKleinCorpus?: boolean;
}

export function Kaartenlijst(props: KaartenlijstProps): JSX.Element {
  const [aantal, zetAantal] = createSignal(CARD_CHUNK_SIZE);
  const [gedwongen, zetGedwongen] = createSignal<string | null>(null);

  // De basisselectie: tekst- en aanbodfilter samen; de status zeeft daar
  // overheen. Precies de EN-combinatie van recomputeBase/applyFilters.
  const basis = createMemo(() => {
    const q = props.filter.tekst();
    let uit = q
      ? (filterIndexRows(
        props.items.map((r) => ({ ...r, title: r.titel, assignee: r.sub })), q,
      ) as unknown as LijstItem[])
      : props.items;
    const off = props.filter.aanbodIri();
    if (off) uit = uit.filter((r) => r.aanbodIris.includes(off));
    return uit;
  });
  const zichtbaar = createMemo(() => basis().filter((r) => props.filter.past(r.status)));
  const getoond = createMemo(() => cardChunk(zichtbaar(), 0, aantal()).items as LijstItem[]);
  const klaar = () => aantal() >= zichtbaar().length;

  // FILTEREN herstart de chunks (setsCardsView.restart) — en ALLEEN filteren.
  // De afhankelijkheid is `filter.stand()`: één waarde uit de ruwe keuzes, die
  // het model niet aanraakt. Dat onderscheid draagt het hele gedrag:
  //
  //   * de rijenlijst wisselt ook zonder dat de lezer iets deed — een
  //     uitgeklapte kaart haalt haar detail op en het model wordt herbouwd — en
  //     aan zo'n herbouw hangt geen herstart-BEDOELING. Hing de herstart daar
  //     toch aan, dan viel de lijst op /brp-ap binnen een halve seconde terug
  //     van 1.392 op 60 kaarten en strandde de sprong halverwege (NB-1), en
  //     verloor wie drie keer "Meer laden" had geklikt zijn 240 kaarten zodra
  //     hij er één uitklapte (I-5);
  //   * een echte filterwissel MOET herstarten, want dat is een andere lijst.
  //
  // De vorige poging hing aan `props.filter.aanbodIri()`, en dát leest via
  // `aanbodOpties()` de model-memo: de draad liep er dus nog steeds heen, alleen
  // langer. `stand()` knipt hem door.
  createEffect(on(() => props.filter.stand(), () => zetAantal(CARD_CHUNK_SIZE),
    { defer: true }));

  // HET SPRONGDOEL wordt opgeruimd zodra het BEREIKT is — niet bij de
  // eerstvolgende herstart (bevinding I-3). Bereikt = de kaart staat getekend;
  // vanaf dat moment houdt de onthouden open-stand haar open en houdt `aantal`
  // haar in beeld, dus het dwingende signaal heeft zijn werk gedaan. Bleef het
  // staan, dan was een tweede sprong naar dezelfde kaart een no-op (het signaal
  // verandert dan niet). In de eerste-beeld-fase blijft het staan: daar geldt de
  // onthouden open-stand niet, dus zonder dwang zou de kaart weer dichtklappen.
  createEffect(() => {
    const doel = gedwongen();
    if (!doel || lijstFase() === 'eerste') return;
    if (getoond().some((r) => r.iri === doel)) zetGedwongen(null);
  });
  // De teller op de sectiekop hoort bij het filter, want hij staat er ook als
  // de sectie ingeklapt is.
  createEffect(() => props.filter.zetTelling(zichtbaar().length, props.items.length));

  const meer = () => zetAantal((n) => Math.min(n + CARD_CHUNK_SIZE, zichtbaar().length));
  // Als MEMO, want elke kaart leest hem: een gewone functie zou `props.items`
  // (een getter) per kaart opnieuw uitlezen.
  const kleinCorpus = createMemo(() => !!props.openBijKleinCorpus
    && !refListCollapsed(props.items.length) && lijstFase() !== 'eerste');

  let sentinel!: HTMLDivElement;
  if (typeof IntersectionObserver !== 'undefined') {
    const io = new IntersectionObserver((rijen) => {
      if (rijen.some((e) => e.isIntersecting) && !klaar()) meer();
    }, { rootMargin: '600px 0px' });
    // Na de eerste render: dán pas bestaat de sentinel.
    queueMicrotask(() => { if (sentinel) io.observe(sentinel); });
    onCleanup(() => io.disconnect());
  }

  // DE SPRONG (revealInUi): sectie openen, een filter dat de kaart verbergt
  // wissen, dóórtekenen tot de kaart in de lijst staat en hem openzetten.
  //
  // EERST DE KLIM. `revealInUi` begint niet met de ref zelf maar met
  // `policyOfRule(iri)` (doc.js r.798-801): een regel, een voorwaarde of een
  // conformsTo-rij hoort bij een KAART, en die kaart moet open zijn voordat de
  // rij überhaupt bestaat — de body is lui. Zonder die stap deed "Toon in
  // document" op een regel letterlijk niets (bevinding C-1). De eigenaar staat
  // al in de invulling-index: die kent per ref de regel én haar herkomst.
  onCleanup(registreerOnthuller((ref: string) => {
    const doel = props.items.some((r) => r.iri === ref) ? ref : eigenaarInLijst(ref, props.items);
    if (!doel) return false;
    props.onOnthul?.();
    if (!zichtbaar().some((r) => r.iri === doel)) props.filter.wis();
    const i = zichtbaar().findIndex((r) => r.iri === doel);
    if (i < 0) return false;
    if (i >= aantal()) zetAantal(i + 1);
    zetGedwongen(doel);
    // Wat de lezer laat openen telt als open — precies wat de bevroren viewer
    // doet, waar `openDetails` in revealInUi het toggle-event afvuurt en
    // `noteToggle` de stand vastlegt. Zo blijft de kaart ook open staan zodra
    // het sprongdoel is opgeruimd (zie de chunk-herstart hierboven).
    onthoudOpen(doel, true);
    return true;
  }));

  return (
    <div class="set-cards">
      <div class="set-card-list">
        <For each={getoond()}>{(item) => (
          <Lijstkaart
            item={item}
            compact={props.compact}
            dwingOpen={gedwongen() === item.iri || kleinCorpus()}
          />
        )}</For>
      </div>
      <div class="card-sentinel" aria-hidden="true" hidden={klaar()} ref={sentinel} />
      <button type="button" class="btn card-more" hidden={klaar()} onClick={meer}>
        {tekst('list.loadMoreRest', { n: zichtbaar().length - aantal() })}
      </button>
    </div>
  );
}
