// DE VERSIENAVIGATOR-CHIP: ‹ datum ›.
//
// Gedragsbron: `versionNav` (met `policyOwnVersion`, `versionPeriod` en
// `stubPolicy`) in de bevroren viewer, viewer-bevroren/assets/doc.js.
//
// Zit rechtsboven in de KOP van elke kaartsoort (aanbod, overeenkomst,
// beleidsset, verzoek en de ?policy=-detailweergave) en vervangt de vroegere
// fold-out versie-kiezer, die op schaal in ingeklapte kaart-body's verstopt zat:
//
//     ‹ 12-12-2012      nieuwste versie: alleen terug
//     ‹ 11-11-2011 ›    tussenversie: beide richtingen
//       10-10-2010 ›    oudste versie: alleen vooruit
//
// De datum is die van de GETOONDE versie (dct:issued, terugval effectiveFrom,
// anders "—"); klikken op de datum opent de volledige lijst ("alle versies
// (n)", recent-first). Een pijl of lijstregel wisselt de kaart naar die versie.
//
// UNIFORM (beslissing eigenaar, aug 2026): ELKE kaartkop draagt de chip, in
// exact dezelfde vorm en breedte — ook een policy zonder versiecontainer. Die
// krijgt zijn eigen datum met twee UITGESCHAKELDE pijlen, zodat de kaartregel
// altijd even hoog is en de pijlen niet verspringen terwijl je bladert. Alleen
// wie niets te dateren én niets te bladeren heeft krijgt geen chip.
//
// SKELETMODUS (?sparql=): de lijst-SELECT levert per kaart maar ÉÉN lid van de
// container; de zusterversies komen pas met het detail-CONSTRUCT. De TELLING
// kent het skelet wel (SKELETON_COUNT_PRED), de RICHTING niet. Eerlijke
// tussenvorm: zijn er aantoonbaar meer versies maar zijn de buren nog onbekend,
// dan staan BEIDE pijlen aan. Een klik laadt eerst het detail (`haalDetail`) en
// corrigeert de stand: ligt er in die richting toch niets, dan wordt de kaart
// met de nu bekende buren opnieuw getekend en dooft die pijl. Beter dan gokken
// op "de getoonde versie is vast de nieuwste".
import { createMemo, createSignal, For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  compactDate, curie, statusWord, versionNavDate, versionNavModel,
} from '../../model/parse.js';
import { detailNodig, endpoint, haalDetail, haalDetails, model } from '../../stores/corpus.js';
import { tekst } from '../../stores/weergave.js';
import type { Policy, Regel } from '../kaart/kaart.jsx';
import './versienav.css';

/** Eén versie binnen een temporele container, zoals `temporal.js` hem levert. */
export interface Versie {
  iri: string;
  title?: string;
  curie?: string | null;
  kind?: string | null;
  status?: string;
  stub?: boolean;
  issued?: string | null;
  effectiveFrom?: string | null;
  effectiveTo?: string | null;
  until?: string | null;
  comment?: string | null;
  sources?: string[];
  obligations?: Regel[];
}

interface NavModel {
  container: { iri: string; title: string; validFrom?: string | null; validTo?: string | null };
  versions: Versie[];
  index: number;
  total: number;
  complete: boolean;
  shown: Versie;
  older: Versie | null;
  newer: Versie | null;
}

function navModel(iri: string): NavModel | null {
  return versionNavModel(model(), iri) as NavModel | null;
}

/** Alle policies van het model, ongeacht soort — de drie lijsten waar zowel
 *  `policyOwnVersion` als `stubSourcePolicy` in zoeken. */
function policyOp(iri: string): Policy | null {
  const m = model() as unknown as
    { sets?: Policy[]; offers?: Policy[]; agreements?: Policy[] } | null;
  if (!m || !iri) return null;
  for (const lijst of [m.sets, m.offers, m.agreements]) {
    const p = (lijst || []).find((x) => x.iri === iri);
    if (p) return p;
  }
  return null;
}

/** De titel die de CONTAINER voor deze versie kent, of `null`. Nodig voor de
 *  plaatshouder van een kaart die naar een versie wisselt die (nog) niet als
 *  policy in het model staat: de titel van de vorige versie zou dan naast de
 *  IRI van de nieuwe staan, en dat is precies de verwarring die bevinding I3
 *  wegnam. De versie zelf staat er wél in — daar kwam de pijl vandaan. */
export function versieTitel(iri: string): string | null {
  const n = navModel(iri);
  return n?.versions.find((v) => v.iri === iri)?.title ?? null;
}

/** Datering van een policy die GEEN versiecontainer heeft, in de vorm die
 *  `versionNavDate` leest. Levert altijd een object: is er niets te dateren,
 *  dan toont de chip "—" (en blijft de kop even hoog als de buurkaarten). */
function eigenVersie(iri: string): Versie {
  const p = policyOp(iri) as (Policy & { version?: { effectiveFrom?: string | null } }) | null;
  return {
    iri,
    issued: (p && p.issued) || null,
    effectiveFrom: (p && p.version && p.version.effectiveFrom) || null,
  };
}

/** "geldig van … tot …" bij een menuregel. */
function versiePeriode(v: Versie): string {
  return v.status === 'future'
    ? tekst('vperiod.from', { date: compactDate(v.effectiveFrom) || '?' })
    : tekst('vperiod.range', {
      from: compactDate(v.effectiveFrom) || '…',
      to: compactDate(v.until) || tekst('vperiod.present'),
    });
}

// --- Beëindigde besluiten ---------------------------------------------------

/** De policy waaruit een STUB-versie zijn regels haalt: de bron-datalaag waar
 *  `prov:wasDerivedFrom` heen wijst (`stubSourcePolicy` in doc.js). */
function stubBron(v: Versie): Policy | null {
  for (const iri of v.sources || []) {
    const p = policyOp(iri);
    if (p) return p;
  }
  return null;
}

/** Een STUB-versie als kaart: het besluit bestaat in het register alleen nog
 *  als documentversie, dus wordt de kaart hier samengesteld in plaats van uit
 *  `model.agreements` gehaald (`stubPolicy` in doc.js).
 *
 *  LEEST HET REACTIEVE MODEL (via `policyOp`), en heeft daarom geen model als
 *  parameter. Er stond er een, met de comment dat hij de aanroeper op hetzelfde
 *  model liet kijken; dat deed hij niet — hij werd weggegooid (`void m`) en elke
 *  waarde gaf hetzelfde resultaat. Weg, dus, in plaats van een comment die iets
 *  anders belooft dan de code doet (bevinding I4). */
export function stubPolicy(v: Versie): Policy {
  const bron = stubBron(v);
  const periode = tekst('stub.period', {
    from: compactDate(v.effectiveFrom) || '…',
    to: compactDate(v.effectiveTo) || compactDate(v.until) || '…',
  });
  // De LAATSTE versie van een beëindigd besluit is niet "vervangen" (er kwam
  // niets voor in de plaats): het besluit is afgelopen. Dat is precies wat de
  // lezer moet weten, dus staat het vooraan in de beschrijving.
  const kop = v.status === 'terminated'
    ? tekst('stub.terminated', { period: periode })
    : tekst('stub.superseded', { period: periode });
  const b = bron as (Policy & { curie?: string | null }) | null;
  return {
    iri: v.iri,
    anon: false,
    stub: true,
    kind: v.kind || 'set',
    curie: v.curie || curie(v.iri),
    title: v.title || v.curie || v.iri,
    // De regels hieronder komen uit de bron-datalaag; zeg dat erbij, anders
    // lijken ze bij het besluit zelf te horen.
    description: (b
      ? tekst('stub.fromSourceLayer', { head: kop, source: b.curie || curie(b.iri) })
      : tekst('stub.documentOnly', { head: kop }))
      + (v.comment ? '\n\n' + v.comment : ''),
    issued: v.issued || null,
    assigner: b ? b.assigner : null,
    assignee: b ? b.assignee : null,
    profile: null,
    permissions: b ? (b.permissions || []) : [],
    prohibitions: b ? (b.prohibitions || []) : [],
    // Verplichtingen: de stub-eigen set (doorwerking vanuit het aanbod, op de
    // stub gematerialiseerd) wint; anders die van de bronlaag.
    obligations: (v.obligations && v.obligations.length)
      ? v.obligations : (b ? (b.obligations || []) : []),
    offers: [],
    extraProps: [],
    version: {
      effectiveFrom: v.effectiveFrom || null,
      effectiveTo: v.effectiveTo || null,
      revisionOf: null,
      derivedFrom: (v.sources || []).map((iri) => ({ iri, curie: curie(iri), label: null })),
      supersededBy: [],
    },
  } as Policy;
}

// --- De chip ----------------------------------------------------------------

export interface VersienavProps {
  /** De IRI van de policy die de kaart NU toont. */
  iri: string;
  /** De kaart moet naar deze versie wisselen. Zonder handler is de chip een
   *  louter informatieve datumweergave. */
  onWissel?: (iri: string) => void;
}

export function Versienav(props: VersienavProps): JSX.Element {
  // ALS MEMO, en dat is geen microoptimalisatie. Deze chip staat op ELKE
  // kaartkop en `nm` wordt er per herrender ~90 keer uit gelezen: `toon()`,
  // `bladerbaar()`, `getoond()`, `bekend()`, `ouder()`, `nieuwer()`,
  // `totaal()`, `openEinde()`, de twee `Show`-condities, de menukop, en per
  // pijl afzonderlijk class/title/aria-label/disabled/aria-hidden/tabindex —
  // in Solid is elk attribuut zijn eigen berekening. Elke uitlezing liep
  // `temporalContainerFor` lineair door alle versiecontainers. Gemeten door het
  // review-seat (teller in `temporalContainerFor`, één taalwissel): vlierdam 102
  // aanroepen per kaart, breda 85; met deze memo 6 respectievelijk 5,3 — 17×
  // minder. De resterende factor (de lineaire scan zelf) is een
  // modellaag-besluit en staat op de eindreview-triage.
  const nm = createMemo(() => navModel(props.iri));
  const getoond = (): Versie => nm()?.shown ?? eigenVersie(props.iri);
  const bladerbaar = () => {
    const n = nm();
    return !!n && (n.total > 1 || !!n.older || !!n.newer);
  };
  const toon = () => bladerbaar() || versionNavDate(getoond()) !== '—';

  const [bezig, zetBezig] = createSignal(false);
  const [fout, zetFout] = createSignal('');
  const [menuOpen, zetMenuOpen] = createSignal(false);
  const [gevuld, zetGevuld] = createSignal(false);

  // Zijn de buren betrouwbaar bekend? Ja zodra de container volledig gelezen
  // is, en ook zodra we het detail van deze policy hebben opgehaald (dan is er
  // niets meer bij te laden en zou een te hoge skelet-telling de pijlen eeuwig
  // aan houden).
  const bekend = () => {
    const n = nm();
    return !n || n.complete || !endpoint() || !detailNodig({ iri: props.iri });
  };
  const ouder = () => (bekend() ? (nm()?.older ?? null) : null);
  const nieuwer = () => (bekend() ? (nm()?.newer ?? null) : null);
  const totaal = () => nm()?.total ?? 1;
  // Skeletstand: meer versies dan we buren kennen → beide pijlen aan.
  const openEinde = () => !bekend() && totaal() > 1;

  const meld = (e: unknown) => {
    zetFout(tekst('vnav.loadFailed', { msg: e instanceof Error ? e.message : String(e) }));
  };

  const ga = async (v: Versie | null) => {
    if (!v || bezig()) return;
    zetBezig(true);
    zetFout('');
    try {
      // ?sparql=-modus: eerst het detail bijladen, anders wisselt de kaart naar
      // een skelet zonder regels. Bij een STUB-versie zit de inhoud niet op de
      // versie zelf maar op zijn bron in de bron-datalaag: laad díe bij.
      if (endpoint()) {
        const doelen = v.stub
          ? (v.sources || []).filter((iri) => !/publicaties\.rvig\.nl|\.pdf$/i.test(iri))
          : [v.iri];
        // PARALLEL, ÉÉN HERBOUW (14 sep 2026, eigenaarsmelding "versies zijn
        // niet echt meer navigeerbaar"). Dit stond als `for`-lus met `await`
        // erin: bij een stub-versie met zes bronnen zijn dat zes ritjes achter
        // elkaar, elk met een volle modelherbouw erachteraan. Op de staande
        // /brp was één versieklik daardoor 10,8-13,0 s waarvan ~7,7 s wachten
        // (meting in het lane-report). De ophaalvolgorde doet er niet toe — de
        // details mengen in dezelfde graaf en de weergave wisselt pas ná
        // afloop — dus deze lus mag in één beurt.
        await haalDetails(doelen.filter((iri) => detailNodig({ iri })));
      }
      props.onWissel?.(v.iri);
    } catch (e) {
      meld(e);
    } finally {
      zetBezig(false);
    }
  };

  // Buur nog onbekend (skeletstand): eerst het detail van DEZE policy laden,
  // dan pas kijken wat er in die richting ligt. Ligt er niets, dan wordt de kop
  // opnieuw getekend — met de nu bekende (en dus gedoofde) stand.
  const zoekUit = async (terug: boolean) => {
    if (bezig()) return;
    zetBezig(true);
    zetFout('');
    let v: Versie | null = null;
    try {
      if (endpoint() && detailNodig({ iri: props.iri })) await haalDetail(props.iri);
      const vers = navModel(props.iri);
      v = (vers && (terug ? vers.older : vers.newer)) || null;
      if (!v) props.onWissel?.(props.iri);
    } catch (e) {
      meld(e);
      zetBezig(false);
      return;
    }
    zetBezig(false);
    if (v) await ga(v);
  };

  // De chip zit in een <summary>: klikken mag de kaart niet in-/uitklappen
  // (zelfde truc als de telling-link `agr-count-link`). Vangnet voor de HELE
  // chip, dus ook een randklik tussen de knoppen.
  const stop = (e: Event) => { e.stopPropagation(); e.preventDefault(); };

  /** Eén pijlsleuf. Beide staan er ALTIJD: een ontbrekende buur levert een
   *  onzichtbare plaatshouder van dezelfde breedte op, zodat datum en pijlen op
   *  exact dezelfde plek blijven terwijl je door de versies loopt.
   *
   *  Die plaatshouder is een ECHTE, uitgeschakelde <button> — geen span met
   *  visibility:hidden, en zeker geen weggelaten element. Een onzichtbare span
   *  vangt geen klik: die viel door naar de <summary> eronder, zodat de kaart
   *  in- en uitklapte precies op de plek waar je zojuist nog aan het bladeren
   *  was. Een disabled button genereert géén click-event. */
  const Pijl = (p: { versie: Versie | null; terug: boolean }): JSX.Element => {
    const leeft = () => !!p.versie || openEinde();
    const label = () => (p.versie
      ? tekst(p.terug ? 'vnav.olderDated' : 'vnav.newerDated',
        { date: versionNavDate(p.versie) })
      : (leeft() ? tekst(p.terug ? 'vnav.older' : 'vnav.newer') : ''));
    return (
      <button
        type="button"
        class={'vnav-arrow' + (leeft() ? '' : ' vnav-arrow-off')}
        title={label() || undefined}
        aria-label={label() || undefined}
        disabled={!leeft()}
        aria-hidden={leeft() ? undefined : 'true'}
        tabindex={leeft() ? undefined : -1}
        onClick={(e) => {
          stop(e);
          if (p.versie) void ga(p.versie); else void zoekUit(p.terug);
        }}
      >
        {p.terug ? '‹' : '›'}
      </button>
    );
  };

  const menuLabel = () => tekst('vnav.allVersions', { n: totaal() });

  /** De volledige lijst (recent-first) — zo blijft alles bereikbaar wat de
   *  fold-out toonde. Pas gevuld bij de eerste opening: op BRP-schaal hangt er
   *  anders per kaart een lijst van tientallen regels in de DOM. */
  const versies = () => (gevuld() ? [...(nm()?.versions || [])].reverse() : []);

  const openMenu = async () => {
    if (!gevuld()) {
      // Skeletstand: de zusterversies zitten nog niet in het model, dus zou het
      // menu één regel tonen terwijl de kop "alle versies (6)" belooft. Eerst
      // het detail bijladen (dat brengt de hele container mee).
      if (!bekend() && endpoint() && detailNodig({ iri: props.iri })) {
        zetBezig(true);
        try { await haalDetail(props.iri); } catch { /* het menu toont wat er is */ }
        zetBezig(false);
      }
      zetGevuld(true);
    }
    zetMenuOpen(!menuOpen());
    // Buiten de chip klikken sluit het menu weer.
    if (menuOpen() && typeof document !== 'undefined') {
      document.addEventListener('click', () => zetMenuOpen(false), { once: true });
    }
  };

  return (
    <Show when={toon()}>
      <span
        class="vnav-wrap"
        onClick={stop}
        onPointerDown={(e) => e.stopPropagation()}
      >
        <span class={bezig() ? 'vnav busy' : 'vnav'}>
          <Pijl versie={ouder()} terug />
          {/* Eén versie: de datum is geen knop (er valt geen lijst te openen),
              maar de twee dode pijlsleuven staan er wél. */}
          <Show
            when={totaal() > 1}
            fallback={(
              <span class="vnav-date mono" title={tekst('vnav.versionDate')}>
                {versionNavDate(getoond())}
              </span>
            )}
          >
            <button
              type="button"
              class="vnav-date mono"
              title={menuLabel()}
              aria-label={tekst('vnav.versionAria', {
                date: versionNavDate(getoond()), menu: menuLabel(),
              })}
              aria-haspopup="true"
              aria-expanded={menuOpen()}
              onClick={(e) => { stop(e); void openMenu(); }}
            >
              {versionNavDate(getoond())}
            </button>
          </Show>
          <Pijl versie={nieuwer()} terug={false} />
        </span>
        <Show when={totaal() > 1}>
          <div class="vnav-menu" hidden={!menuOpen()}>
            <Show when={gevuld() && nm()}>{(n) => (
              <>
                <div class="vnav-menu-head muted">{tekst('vnav.allVersions', {
                  n: n().versions.length,
                })}</div>
                <div class="vnav-menu-sub muted">
                  {n().container.title
                    + ((n().container.validFrom || n().container.validTo)
                      ? tekst('vnav.validity', {
                        from: compactDate(n().container.validFrom) || '…',
                        to: compactDate(n().container.validTo) || '…',
                      }) : '')}
                </div>
              </>
            )}</Show>
            <For each={versies()}>{(v) => {
              const isGetoond = () => v.iri === props.iri;
              return (
                <button
                  type="button"
                  class={'vnav-mi' + (isGetoond() ? ' shown' : '')}
                  title={versiePeriode(v)}
                  aria-current={isGetoond() ? 'true' : undefined}
                  onClick={(e) => {
                    stop(e);
                    zetMenuOpen(false);
                    if (!isGetoond()) void ga(v);
                  }}
                >
                  <span class="vnav-mi-date mono">{versionNavDate(v)}</span>
                  <span class={'vchip ' + (v.status || '')}>{statusWord(v.status)}</span>
                  <span class="vnav-mi-title">{v.title}</span>
                </button>
              );
            }}</For>
          </div>
        </Show>
        <Show when={fout()}><span class="src-err">{fout()}</span></Show>
      </span>
    </Show>
  );
}
