// DE LEDENLIJST VAN EEN COLLECTIE — de doorlopende partOf-boom, als tabel.
//
// Een collectie-lidmaatschap is zelden één laag diep: een stuk zit in een
// dossier, dat in een serie, die in een archief; het BRP-informatiemodel kent
// rubriek > groep > categorie. De lijst toont daarom niet alleen de directe
// leden — een lid dat zélf leden heeft is een uitklapbare knoop, met op elk
// niveau dezelfde groepering en telling. Het modelwerk (groepering, ancestry,
// cykeldetectie, "heeft dit lid zelf leden") zit in `memberTreeLevel`; hier
// staat alleen de weergave en het lui bijladen.
//
// Gedragsbron: targetMembersFold / openMemberLevel / renderMemberLevel /
// memberBranch / memberLeaf in de bevroren viewer (viewer-bevroren/assets/doc.js).
//
// VERBETERING 1 (besluit 4 sep) — TABEL MET INKLAP-DREMPEL. Twee afwijkingen
// van de bevroren weergave, allebei bewust:
//
//  a. TABEL IN PLAATS VAN GROEPSKOPPEN. De oude lijst zette het type van de
//     leden als kop bóven een <ul> ("Rubriek (69)"), en herhaalde die kop per
//     groep. Het type is een EIGENSCHAP van elk lid, geen kopje: als kolom
//     ernaast is het per rij afleesbaar, staat elke rij op dezelfde hoogte, en
//     verdwijnt de ruis van koppen tussen de rijen door. Een lid zonder type
//     krijgt een streepje — een leeg veld, niet een restcategorie.
//  b. DE FOLD-OUT VOLGT `refListCollapsed()`. De oude fold-out stond ALTIJD
//     dicht, ook bij drie leden; dan is de klik zuivere overhead en zie je van
//     een kleine verzameling niets. Boven de drempel blijft hij dicht: daar is
//     de telling het antwoord en zou de lijst de kaart platwalsen. De regel is
//     niet nieuw — hij staat al als `refListCollapsed` in parse.js en de
//     bevroren viewer past hem op elke andere verwijzingslijst toe; nieuw is
//     alleen dat de LEDENLIJST hem nu ook volgt (en de terugverwijzingen
//     ernaast, zie terugverwijzingen.tsx).
//
// LUI PER NIVEAU, in beide modi (ongewijzigd t.o.v. de bevroren viewer):
//   ttl-modus      — de graaf is compleet; uitklappen is puur weergavewerk.
//   ?sparql=-modus — elk uitklappen kost ÉÉN CONSTRUCT (haalCollectieNiveau in
//                    de corpus-store): de leden met label/type, plus de
//                    lidmaatschappen één niveau dieper zodat de boom weet wélke
//                    leden opnieuw uitklapbaar zijn.
//
// DE OPEN-STAND OVERLEEFT EEN HERRENDER (golf C, punt 2). De sleutels die deze
// component stempelt — `coll:<iri>` op de lijst, `tree:<pad>` op elke tak —
// zijn óók de sleutels waaronder hij zijn stand bewaart, in de gedeelde
// corpus-administratie van `stores/openstand.ts` (de `openState`-set van de
// bevroren viewer). Een taalwissel, een fasewissel of een herladen pagina laat
// de boom dus staan zoals de lezer hem achterliet.
//
// WAT HIER (NOG) NIET IN ZIT: de intensionele definitie van een collectie (de
// refinement-chips — die horen bij de voorwaarden-familie van taak 5) en de
// bewerk-affordances (deeltraject 3).
import { createEffect, createMemo, createSignal, For, Match, Show, Switch } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  MEMBER_TREE_MAX_DEPTH, groupCollectionMembers, memberSummary,
  memberTreeLevel, refListCollapsed,
} from '../../model-grens.js';
import type { LedenGroep, LedenNiveau, Lid, Term } from '../../model-grens.js';
import { endpoint, graaf, graafVersie, haalCollectieNiveau } from '../../stores/corpus.js';
import { staatOpen, zetOpen } from '../../stores/openstand.js';
import { vouwstand } from '../gedeeld/vouwstand.js';
import { tekst } from '../../stores/weergave.js';
import { Chevron } from '../gedeeld/chip.jsx';
import './leden.css';
import { kopBediening, selectieBinnen } from '../gedeeld/kopselectie.js';

/** DE OPEN-STAND VAN DE TAKKEN, buiten de tabelrijen om.
 *
 *  Waarom niet gewoon een signal per rij: elke herberekening van een niveau
 *  levert VERSE rij-objecten op, en `<For>` is in Solid gekeyd op referentie —
 *  de `LidRij`-componenten worden dan vernietigd en met hen hun open-stand. In
 *  endpointmodus is dat geen randgeval maar het normale verloop: het uitklappen
 *  van een tak haalt zelf een niveau bij en schuift daarmee `graafVersie` op,
 *  dus juist de tak die de lezer net opende zou weer dichtklappen (bevinding
 *  C-1). De stand hangt daarom aan een STABIELE SLEUTEL — het pad van de wortel
 *  naar het lid — die een herbouw overleeft.
 *
 *  Die sleutel is ook het adres waarop de open-stand van het DOCUMENT deze tak
 *  terugvindt (`data-open-key`, zie `takSleutel`), en sinds golf C is dat
 *  dezelfde administratie: de takken staan in de corpus-set van
 *  `stores/openstand.ts`, naast de open kaarten — precies één `openState` per
 *  corpus, zoals in de bevroren viewer. Daarmee overleeft een open tak niet
 *  alleen de herberekening van zijn niveau, maar ook een taalwissel, een
 *  fasewissel en een herladen pagina. */
export interface OpenStand {
  open(sleutel: string): boolean;
  zet(sleutel: string, open: boolean): void;
}

const BOOMSTAND: OpenStand = { open: staatOpen, zet: zetOpen };

/** Het adres van één tak: het volledige PAD van de wortel van de ledenlijst
 *  naar dit lid. Zelfde vorm als de bevroren viewer stempelde
 *  (`'tree:' + [...ancestors, m.iri].join('|')`, doc.js) — hetzelfde lid kan
 *  onder twee ouders hangen, en die takken zijn afzonderlijk open of dicht. */
function takSleutel(pad: string[], iri: string): string {
  return 'tree:' + [...pad, iri].join('|');
}

/** Een collectie zoals `collectionRef` hem aan een target of een partij hangt.
 *  De DIRECTE leden komen als gegeven mee (die staan al in het model); de boom
 *  eronder leest deze component zelf uit de graaf. */
export interface CollectieDesc {
  iri?: string | null;
  curie?: string | null;
  label?: string | null;
  /** Een anonieme collectie: geen IRI om op na te vragen, wel een blanke term
   *  waarmee de graaf te bevragen is. */
  anon?: boolean;
  term?: Term;
  members?: Lid[];
  /** 'asset' | 'party' — bepaalt de woordkeuze van de telling. */
  collKind?: string | null;
}

/** De naam van een lid.
 *
 *  Dit was tot 16 sep 2026 een `<a href="?verken=…">` naar diezelfde knoop in
 *  de RDF-verkenner. De verkenner is gesloopt (eigenaarsbesluit), en daarmee
 *  had deze link geen bestemming meer. Hij is dus tekst geworden — dezelfde
 *  vorm die een lid ZONDER adres hier altijd al had, en die de ledenlijst met
 *  `.member-name` al styleert. De omschrijving blijft als hover staan; dat was
 *  het enige wat de link verder nog droeg. */
function LidNaam(props: { lid: Lid }): JSX.Element {
  return (
    <span class="member-name" title={props.lid.desc || undefined}>{props.lid.label}</span>
  );
}

interface NiveauOpties {
  kind: string | null;
  /** Het pad van de wortel van de ledenlijst tot en met de wortel van DIT
   *  niveau — elke knoop één keer. Draagt drie dingen tegelijk: de
   *  cykeldetectie van `memberTreeLevel`, de ancestry-wortels, en de sleutel
   *  waaronder de open-stand van een tak wordt onthouden. */
  ancestors: string[];
  depth: number;
  stand: OpenStand;
}

/** Eén tabelrij: naam (met uitklapknop als het lid zelf leden heeft) en soort.
 *  Staat de rij open, dan volgt er een rij met het niveau eronder. */
function LidRij(props: { lid: Lid; soort: string | null; opties: NiveauOpties }): JSX.Element {
  const sleutel = () => takSleutel(props.opties.ancestors, props.lid.iri);
  const open = () => props.opties.stand.open(sleutel());
  const heeftLeden = () => !!props.lid.hasChildren && !props.lid.cycle;
  // Diepte-limiet: onder MEMBER_TREE_MAX_DEPTH stopt de boom. Hij verwees
  // daarvoor door naar de RDF-verkenner (gesloopt 16 sep 2026); wat er nu staat
  // is de kale mededeling dát hij stopt.
  const tak = () => heeftLeden() && props.opties.depth < MEMBER_TREE_MAX_DEPTH;
  const dieper = () => heeftLeden() && props.opties.depth >= MEMBER_TREE_MAX_DEPTH;
  // DE HELE RIJ IS HET KLIKDOEL (eigenaarsverzoek 16 sep 2026: "Je kan ook niet
  // op de hele regel klikken maar echt alleen op de chevron zelf"). De klik
  // landt op de <tr> en niet op de knop: een tabelrij kan geen <button> zijn en
  // een knop kan geen twee cellen spannen, dus is de RIJ de kop en is de knop
  // alleen nog de zichtbare affordance plus het toetsenbordanker. De knop
  // draagt daarom géén eigen `onClick` meer — zijn klik (ook die van Enter of
  // spatie) bubbelt naar deze handler, en twee handlers zouden elkaar opheffen.
  //
  // Dezelfde selectiebescherming als elke <summary>-kop (`kopBediening`): wie
  // een lidnaam doorheen sleept om hem te kopiëren, hoort geen tak te openen.
  const klik = (e: MouseEvent): void => {
    if (!tak()) return;
    const rij = e.currentTarget as HTMLElement;
    if (selectieBinnen(rij)) return;
    props.opties.stand.zet(sleutel(), !open());
  };
  return (
    <>
      <tr
        class="member-row"
        classList={{ 'member-tak': tak() }}
        data-iri={props.lid.iri}
        data-ref={props.lid.iri}
        title={props.lid.iri}
        onClick={klik}
      >
        <td class="member-name-cell">
          <LidNaam lid={props.lid} />
          {/* Twee neutrale mededelingen over waaróm de boom hier stopt — geen
              foutmeldingen: een ring in odrl:partOf is data, geen crash. */}
          <Show when={props.lid.cycle}>
            <span class="tree-note muted" title={tekst('tree.cycleTitle')}>
              {tekst('tree.cycle')}
            </span>
          </Show>
          <Show when={dieper()}>
            <span class="tree-note muted" title={tekst('tree.deeperTitle')}>
              {tekst('tree.deeper')}
            </span>
          </Show>
        </td>
        <td class="member-type muted">{props.soort || tekst('members.typeNone')}</td>
        {/* DE CHEVRON STAAT RECHTS, als LAATSTE element van de regel — de regel
            van gedeeld.css ("altijd als laatste element van een kopregel"), hier
            als eigen kolom omdat de soortkolom ertussen staat. De cel blijft ook
            op bladrijen staan: zonder die lege cel zou de soortkolom per rij
            verspringen. */}
        <td class="member-chev-cell">
          <Show when={tak()}>
            <button
              type="button"
              class="member-toggle"
              // Het adres van deze tak voor de open-stand-herinnering (taak 3):
              // op de knop die hem opent, met `aria-expanded` als leesbare
              // stand — het equivalent van de `<details open>` van de bevroren
              // viewer. De component leest hem zelf niet.
              data-open-key={sleutel()}
              aria-expanded={open()}
              title={tekst('tree.expand')}
            ><Chevron klein /></button>
          </Show>
        </td>
      </tr>
      <Show when={open()}>
        <tr class="member-sublevel">
          <td colspan="3">
            {/* `ancestors` is het pad TOT dit lid; het niveau eronder zet zijn
                eigen wortel — dit lid — er zelf achter. Nog een keer meegeven
                zou elke tussenknoop dubbel in het pad zetten, en daarmee in de
                sleutel van elke tak eronder. */}
            <Niveau
              wortel={props.lid.iri}
              kind={props.opties.kind}
              ancestors={props.opties.ancestors}
              depth={props.opties.depth + 1}
              stand={props.opties.stand}
            />
          </td>
        </tr>
      </Show>
    </>
  );
}

/** De leden van één (deel)groepering als tabel. Het TYPE staat als kolom naast
 *  de naam; de rijen houden de volgorde van de modelgroepering (op klasselabel,
 *  daarbinnen op naam, typeloze leden achteraan), zodat de tabel dezelfde
 *  ordening leest als de oude groepskoppen — alleen zonder de koppen. */
function LedenTabel(props: {
  groepen: LedenGroep[]; opties: NiveauOpties; kop?: boolean;
}): JSX.Element {
  const rijen = () => props.groepen.flatMap(
    (g) => g.items.map((lid) => ({ lid, soort: g.typed ? g.label : null })),
  );
  return (
    <Show when={rijen().length}>
      <table class="member-table">
        {/* De kolomkoppen staan ALLEEN op het bovenste niveau. Elke tak zijn
            eigen "Naam | Soort" zou de boom vullen met herhaling van iets wat
            de lezer al weet — de kolommen zijn overal dezelfde. */}
        <Show when={props.kop}>
          <thead>
            <tr>
              <th scope="col">{tekst('members.colName')}</th>
              <th scope="col" class="member-type-col">{tekst('members.colType')}</th>
              {/* De chevronkolom heeft geen kop: hij draagt geen gegeven maar
                  de bediening van de rij. Een leeg <th> houdt wel de
                  kolomtelling van de tabel kloppend. */}
              <th scope="col" class="member-chev-cell" />
            </tr>
          </thead>
        </Show>
        <tbody>
          <For each={rijen()}>{(r) => (
            <LidRij lid={r.lid} soort={r.soort} opties={props.opties} />
          )}</For>
        </tbody>
      </table>
    </Show>
  );
}

/** Eén niveau van de boom.
 *
 *  `vast` is de terugval voor een ANONIEME collectie zonder term: die is niet
 *  in de graaf na te vragen, dus daar zijn de leden uit het model alles wat er
 *  is — en dan is er ook niets uit te klappen. */
function Niveau(props: {
  wortel: Term | string | null;
  kind: string | null;
  ancestors: string[];
  depth: number;
  stand: OpenStand;
  vast?: Lid[];
}): JSX.Element {
  const [bijgeladen, setBijgeladen] = createSignal(0);
  const [bezig, setBezig] = createSignal(false);

  // Endpointmodus: één CONSTRUCT per niveau, één keer. De store bewaakt dat
  // (niveauGeladen), zodat dichtklappen en opnieuw openen geen tweede hop kost.
  createEffect(() => {
    const w = props.wortel;
    if (typeof w !== 'string' || !endpoint()) return;
    setBezig(true);
    haalCollectieNiveau(w)
      .then((nieuw) => { if (nieuw) setBijgeladen((n) => n + 1); })
      .finally(() => setBezig(false));
  });

  const niveau = createMemo<LedenNiveau | null>(() => {
    if (props.vast) {
      return {
        total: props.vast.length,
        members: props.vast,
        ancestry: [],
        groups: groupCollectionMembers(props.vast, props.kind),
      };
    }
    const g = graaf();
    if (!g || !props.wortel) return null;
    // Twee redenen om opnieuw te lezen: de store kreeg een nieuwe graaf, of er
    // is materiaal ín deze graaf bij gemengd (endpoint-hop).
    void graafVersie();
    void bijgeladen();
    return memberTreeLevel(g, props.wortel, { kind: props.kind, ancestors: props.ancestors });
  });

  // HET PAD naar beneden, inclusief de wortel van DIT niveau. Zonder die eigen
  // wortel raakt de cykeldetectie hem kwijt: `memberTreeLevel` legt hem alleen
  // in zijn eigen pad, en het niveau eronder krijgt hem dan niet mee. De
  // bevroren viewer heeft dat gat (memberBranch geeft alleen de LID-IRI door),
  // waardoor een ring pas één niveau later wordt herkend. Hier klopt het pad,
  // en daarmee de mededeling "komt hierboven al voor".
  const pad = (): string[] => {
    const w = props.wortel;
    return typeof w === 'string' ? [...props.ancestors, w] : props.ancestors;
  };
  const opties = (): NiveauOpties => ({
    kind: props.kind, ancestors: pad(), depth: props.depth, stand: props.stand,
  });

  // Drie standen. De LAADREGEL verschijnt alleen als er nog niets te tonen is:
  // staat er al materiaal in de graaf, dan is dat beter dan een laadregel die
  // er even overheen flitst — en is er niets, dan zou een traag endpoint als
  // lege lijst lezen, precies het misverstand dat deze regel voorkomt.
  const stand = (): 'laden' | 'leeg' | 'vol' => {
    const nv = niveau();
    if (nv && nv.total) return 'vol';
    if (!nv || bezig()) return 'laden';
    return 'leeg';
  };

  // ÉÉN VLAKKE LIJST BLOKKEN in plaats van geneste lussen. Twee redenen: de
  // kolomkoppen mogen per niveau maar één keer staan (en met geneste lussen is
  // "de eerste tabel" niet aan te wijzen), en de ancestry-koppen zijn geen
  // container maar een TUSSENKOP — de rijen eronder horen bij hetzelfde niveau.
  //
  // Volgorde: eerst de ANCESTRY — de keten BOVEN de leden, buiten deze
  // collectie om (BRP: categorie, daaronder groep) — met per groep haar eigen
  // leden en dan haar subgroepen; daarna alles wat zo'n keten niet heeft, in de
  // vertrouwde type-ordening.
  interface Blok { kop?: string; sub?: boolean; groepen: LedenGroep[] }
  const blokken = createMemo<Blok[]>(() => {
    const nv = niveau();
    if (!nv || !nv.total) return [];
    const uit: Blok[] = [];
    for (const g of nv.ancestry) {
      uit.push({
        kop: `${g.label} (${g.count})`,
        groepen: groupCollectionMembers(g.items, props.kind),
      });
      for (const s of g.subgroups) {
        uit.push({
          kop: `${s.label} (${s.items.length})`,
          sub: true,
          groepen: groupCollectionMembers(s.items, props.kind),
        });
      }
    }
    if (nv.groups.some((g) => g.items.length)) uit.push({ groepen: nv.groups });
    return uit;
  });
  // Waar de kolomkoppen staan: op het bovenste niveau, boven de eerste tabel
  // die daadwerkelijk rijen heeft. -1 = nergens.
  const kopOp = (): number => (props.depth === 1
    ? blokken().findIndex((b) => b.groepen.some((g) => g.items.length))
    : -1);

  return (
    <div class="member-niveau">
      <Switch>
        <Match when={stand() === 'laden'}>
          <div class="member-loading muted">{tekst('tree.loading')}</div>
        </Match>
        <Match when={stand() === 'leeg'}>
          <div class="member-empty muted">{tekst('tree.empty')}</div>
        </Match>
        <Match when={stand() === 'vol'}>
          <For each={blokken()}>{(b, i) => (
            <>
              <Show when={b.kop}>
                <div class={b.sub ? 'member-ancestry-sub muted' : 'member-ancestry-head muted'}
                  title={b.sub ? tekst('tree.ancestrySubTitle') : tekst('tree.ancestryTitle')}
                >{b.kop}</div>
              </Show>
              <LedenTabel groepen={b.groepen} opties={opties()} kop={kopOp() === i()} />
            </>
          )}</For>
        </Match>
      </Switch>
    </div>
  );
}

export interface LedenProps {
  /** De collectie zoals het model hem oplevert (target of partij). */
  desc: CollectieDesc;
}

/** De ledenlijst van een collectie: een telling die uitklapt naar de boom. */
export function Leden(props: LedenProps): JSX.Element {
  const leden = () => props.desc.members || [];
  const soort = () => props.desc.collKind || 'asset';
  // DE STARTSTAND IS DE BASELINE-REGEL `refListCollapsed()`: tot en met
  // REF_LIST_INLINE_MAX rijen direct getoond, daarboven ingeklapt met alleen
  // een telling. Dezelfde functie die de bevroren viewer op elke andere
  // verwijzingslijst toepast ("Overeenkomsten op dit aanbod"), en die de
  // terugverwijzingen hiernaast nu ook gebruiken — zo slaat dezelfde
  // hoeveelheid rijen in deze viewer overal op hetzelfde getal om.
  // Heeft de lezer zelf geklikt, dan wint die keuze: `handmatig` blijft `null`
  // tot dat gebeurt, zodat een lijst die hij dichtklapte niet terugspringt.
  //
  // En daarvóór wint wat hij de VORIGE keer openzette: `coll:<iri>` in de
  // open-stand van het corpus. Alleen als OPENZETTER — de bewaarde set noemt
  // wat open stond, niet wat dicht stond, dus een lijst die hier onder de
  // drempel toch al openstaat blijft open (zoals restoreListUi ook alleen
  // opende en nooit dichtklapte).
  //
  // FIXRONDE 1 (dt3 lane-toevoegfocus): `handmatig` was een COMPONENT-LOKAAL
  // signaal, en dat overleeft de hermontage na een mutatie niet. Een blok dat de
  // lezer expliciet dichtklapte stond na een "+ toestemming" in dezelfde kaart
  // ineens weer open, want de bewaarde set noemt alleen wat OPEN stond en de
  // sluiting was daarmee nergens vastgelegd. Hij woont nu in de
  // open-stand-administratie, driestandig, onder dezelfde `coll:`-sleutel — zie
  // `ui/gedeeld/vouwstand.ts` voor de drie standen en de reden dat hij vluchtig
  // is.
  const sleutel = () => (props.desc.iri ? 'coll:' + props.desc.iri : '');
  const vouw = vouwstand(sleutel);
  const open = () => vouw.handmatig()
    ?? (staatOpen(sleutel()) || !refListCollapsed(leden().length));
  // Lui: het eerste niveau wordt pas gebouwd bij de eerste uitklap.
  const [gebouwd, setGebouwd] = createSignal(false);
  createEffect(() => { if (open()) setGebouwd(true); });
  // De open-stand van de TAKKEN staat in de corpus-administratie (BOOMSTAND):
  // de tabellen worden bij elke graafVersie-bump opnieuw gebouwd (bevinding
  // C-1), en een herrender bouwt zelfs de hele kaart opnieuw op.
  const stand = BOOMSTAND;

  const wortel = (): Term | string | null => {
    if (props.desc.anon) return props.desc.term || null;
    return props.desc.iri || null;
  };

  return (
    <details
      class="member-list"
      data-open-key={sleutel() || undefined}
      open={open()}
      onToggle={(e) => {
        const aan = (e.currentTarget as HTMLDetailsElement).open;
        vouw.onthoud(aan);
        zetOpen(sleutel(), aan);
      }}
    >
      <summary class="member-sum muted" {...kopBediening()}>
        <span class="member-count">{memberSummary(leden(), soort())}</span>
        <Chevron klein />
      </summary>
      <div class="member-tree">
        <Show when={gebouwd()}>
          <Niveau
            wortel={wortel()}
            kind={soort()}
            ancestors={[]}
            depth={1}
            stand={stand}
            vast={wortel() ? undefined : leden()}
          />
        </Show>
      </div>
    </details>
  );
}
