// DE TWEE REGISTRATIES VAN DE APP-SCHIL.
//
// De bevroren viewer doet dit bij het opstarten, op moduleniveau in doc.js
// (r.151 en r.156), vóór de taalkeuze en vóór de eerste render:
//
//   registerPrefixes(DEFAULT_REGISTER_PREFIXES);
//   registerLabelKeys(DEFAULT_PROPERTY_LABEL_KEYS);
//
// De nieuwe app deed het nergens. Gevolg, gevonden in de side-by-side van taak
// 8a: `dct:source` heet in de oude viewer "bron (dct:source)" en in de nieuwe
// "source (dct:source)" — de kale localName. Dat raakt de HELE leesviewer
// (kaarten, zijnav, verkenner), niet één stand, en hoort daarom in de schil.
//
// Waarom het twee registraties zijn en geen tabel in de UI:
//  - de PREFIXEN zijn nodig voor curie() zodra er geen bron met @prefix-
//    declaraties is (de bronloze endpoint-modus). Bron-declaraties zijn
//    identiek en winnen niet: eerste registratie wint.
//  - de LABELSLEUTELS zijn de laatste terugval vóór een kale localName. Ze
//    registreren i18n-SLEUTELS, geen teksten: labelFor vertaalt ze pas bij het
//    renderen, zodat een taalwissel deze namen meeneemt. Een label uit de bron
//    zelf (rdfs:label/skos:prefLabel/dct:title) wint altijd.
import { registerLabelKeys, registerPrefixes } from './model-grens.js';
import { DEFAULT_PROPERTY_LABEL_KEYS } from './model/register-labels.js';
import { DEFAULT_REGISTER_PREFIXES } from './model/register-prefixes.js';

/** Registreer de meegeleverde prefixen en weergavenamen. Idempotent (eerste
 *  registratie wint), maar hoort één keer te draaien: in de app-boot, vóór de
 *  eerste render. */
export function registreerStandaarden(): void {
  registerPrefixes(DEFAULT_REGISTER_PREFIXES);
  registerLabelKeys(DEFAULT_PROPERTY_LABEL_KEYS);
}
